local config = {
  ui_story_5060_50600101_1_dialog_content = "A photography contest right in the shopping district, and the grand prize is an overseas vacation for two!",
  ui_story_5060_50600101_2_dialog_content = "With that, I could go on a romantic getaway with <color=#FFB400>Kobayashi</color>!",
  ui_story_5060_50600101_3_dialog_content = "And what better way to win than by taking pictures of the scenery from our home world! I really am a genius, huh?",
  ui_story_5060_50600101_4_dialog_content = "Hey, Tohru. Didn't you say we were going back to gather some exotic food ingredients?",
  ui_story_5060_50600101_5_dialog_content = "Why are you still on about that? Don't worry, we can gather all the ingredients we need while we're out taking pictures!",
  ui_story_5060_50600101_6_dialog_content = "Well, never mind. We don't have time to argue about this. Right this way, everyone!",
  ui_story_5060_50600101_7_dialog_content = "Activating the <color=#FFB400>teleportation portal</color>—",
  ui_story_5060_50600101_8_dialog_content = "Alright everyone, prepare to finally see our hometown!",
  ui_story_5060_50600101_9_dialog_content = "Huh? Wait...",
  ui_story_5060_50600101_10_dialog_content = "<size=50>What is this place?!</size>",
  ui_story_5060_50600101_11_dialog_content = "Activating the portal! Hrrrng—! Come on, activate!",
  ui_story_5060_50600101_12_dialog_content = "Strange, the portal won't turn on at all.",
  ui_story_5060_50600101_13_dialog_content = "Oh, this is bad... Are Kanna and Elma stuck here with no way back too?",
  ui_story_5060_50600101_14_dialog_content = "Okay, just calm down and take in the surroundings... Some things in this world I could recognize.",
  ui_story_5060_50600101_15_dialog_content = "It's not much different than Kobayashi's world. For example, there are convenience stores and public transportation here too...",
  ui_story_5060_50600101_16_dialog_content = "Well, I'm going with this mechanical doll.",
  ui_story_5060_50600101_17_dialog_content = "Your taste is impeccable, ma'am! Your daughter will absolutely love this cute and obedient present!",
  ui_story_5060_50600101_18_dialog_content = "Please have it wrapped up quickly. I need to catch the airship to Shuttle Hub.",
  ui_story_5060_50600101_19_dialog_content = "Consider it done, ma'am! Thanks a lot for shopping with us!",
  ui_story_5060_50600101_20_dialog_content = "You! Disrupting the street order with <color=#FFB400>Luminatics</color> is strictly forbidden here!",
  ui_story_5060_50600101_21_dialog_content = "Hey, I'm talking about you! The <color=#FFB400>demi-human</color> messing with fire there! Stop your street show! Right now!",
  ui_story_5060_50600101_22_dialog_content = "My bad! Sorry! I'll go now... Ouch, that hurts!",
  ui_story_5060_50600101_23_dialog_content = "How come the God of Light chose to bless troublemakers like you with Luminatics...",
  ui_story_5060_50600101_24_dialog_content = "Hey! What are you looking at? Stand back! Don't block the way!",
  ui_story_5060_50600101_25_dialog_content = "...",
  ui_story_5060_50600101_26_dialog_content = "What's going on? Are the demi-humans causing troubles again? Stay away from 'em, everyone...",
  ui_story_5060_50600101_27_dialog_content = "Um... There are similar <color=#FFB400>demi-human races</color> and <color=#FFB400>magics</color> in my homeland as well...",
  ui_story_5060_50600101_28_dialog_content = "But here, they call them <color=#FFB400>demi-human Aurorians</color> and <color=#FFB400>Luminatics</color>, right?",
  ui_story_5060_50600101_29_dialog_content = "There's something strange about the <color=#FFB400>mana</color> in this world, and it's preventing me from <color=#FFB400>turning back into a dragon</color>. If it weren't for my powers being limited...",
  ui_story_5060_50600101_30_dialog_content = "I'd teach these high and mighty knights a lesson right now!",
  ui_story_5060_50600101_31_dialog_content = "That floating white castle up there looks pretty suspicious. I bet it's the base of operations for these knights.",
  ui_story_5060_50600101_32_dialog_content = "Stuck in a strange new world with limited powers, and under the cautious stares of some of its residents...",
  ui_story_5060_50600101_33_dialog_content = "In such a situation, should I use force to intimidate the people around me first?",
  ui_story_5060_50600101_34_dialog_content = "That way, I can buy myself more time to gather my strength and search for Kanna and the others.",
  ui_story_5060_50600101_35_dialog_content = "Urgh... No, I think I need to replenish my energy first. I wonder what money looks like in this world?",
  ui_story_5060_50600101_36_dialog_content = "Freshly baked Longzhou pastries! Delectable and light on the tongue! Hey there, young lady, fancy a bite?",
  ui_story_5060_50600101_37_dialog_content = "A bite? Does that mean it's free?",
  ui_story_5060_50600101_38_dialog_content = "Absolutely! Have a try first, and buy some if you like the taste. We even do deliveries, so you can send some to your far-off friends.",
  ui_story_5060_50600101_39_dialog_content = "(I do need to confirm whether or not we can safely eat the food in this world...)",
  ui_story_5060_50600101_40_dialog_content = "Hmm? This is actually pretty good!",
  ui_story_5060_50600101_41_dialog_content = "Wow! Impressive!",
  ui_story_5060_50600101_42_dialog_content = "You handle those chopsticks with finesse. Ever been to <color=#FFB400>Longzhou</color>?",
  ui_story_5060_50600101_43_dialog_content = "Huh? Not at all. Where is this \"Longzhou\" place?",
  ui_story_5060_50600101_44_dialog_content = "It's my birthplace, an overseas continent with a thriving culture and scrumptious food. My place, Liu's Restaurant, specializes in Longzhou cuisine.",
  ui_story_5060_50600101_45_dialog_content = "(Longzhou... Does this restaurant have anything to do with the dragons I'm looking for?)",
  ui_story_5060_50600101_46_dialog_content = "And what's this place?",
  ui_story_5060_50600101_47_dialog_content = "Here is Lower Lumopolis, the heart of <color=#FFB400>Astra</color>. We have merchants from all over the continent here—",
  ui_story_5060_50600101_48_dialog_content = "Hold on, miss, are you lost?",
  ui_story_5060_50600101_49_dialog_content = "In a way, yes. To be honest, I'm not sure what happened either.",
  ui_story_5060_50600101_50_dialog_content = "Are you suffering memory loss or abduction?! If you're in trouble, we're all here to lend a hand!",
  ui_story_5060_50600101_51_dialog_content = "How about coming inside for a warm drink and a break?",
  ui_story_5060_50600101_52_dialog_content = "(The people here can be really nice too...)",
  ui_story_5060_50600101_53_dialog_content = "Thank you. I got separated from my friends. I just need to find them before going home.",
  ui_story_5060_50600101_54_dialog_content = "There's something I'd like to ask of you... Pardon, but may I ask your name?",
  ui_story_5060_50600101_55_dialog_content = "I'm the owner and chef of Liu's Restaurant. You can just call me Liu.",
  ui_story_5060_50600101_56_dialog_content = "If you need any help, miss, just let me know!",
  ui_story_5060_50600101_57_dialog_content = "Allow me to introduce myself. My name is Tohru, and I was wondering... May I work in your restaurant for a little while?",
  ui_story_5060_50600101_58_dialog_content = "I know we've just met, and I still have so much to learn about this place... But my skills as a maid are top-notch!",
  ui_story_5060_50600101_59_dialog_content = "Cooking, cleaning, and greeting guests are like second nature to me! I'm sure I can be of use to your restaurant!",
  ui_story_5060_50600101_60_dialog_content = "Here is your order of Snowy Tofu! Please enjoy!",
  ui_story_5060_50600101_61_dialog_content = "Wow, impressive! The food here is served really quick.",
  ui_story_5060_50600101_62_dialog_content = "Here is Chef Liu's newest special: Golden Seafood Soup! Please be careful, as it's very hot!",
  ui_story_5060_50600101_63_dialog_content = "Oh, okay.",
  ui_story_5060_50600101_64_dialog_content = "Here's a new pair of chopsticks. If you have trouble using them... We have knives and forks too! Here you go!",
  ui_story_5060_50600101_65_dialog_content = "Tohru, we've got some customers!",
  ui_story_5060_50600101_66_dialog_content = "Got it! Ready, everyone? One, two, three—",
  ui_story_5060_50600101_67_dialog_content = "Welcome!",
  ui_story_5060_50600101_68_dialog_content = "I must say, today was quite a shock. I hardly ever see this many customers looking so at ease and happy here.",
  ui_story_5060_50600101_69_dialog_content = "Your performance was truly outstanding, Miss Tohru! This commitment to service is what you'd call the maid spirit...",
  ui_story_5060_50600101_70_dialog_content = "That's right! This is the spirit of a true maid's dedication!",
  ui_story_5060_50600101_71_dialog_content = "Oh dear, I never thought I'd get the chance to pick up something so new and exciting at this age.",
  ui_story_5060_50600101_72_dialog_content = "The same goes for me! I've learned so much from the way you discern and prepare your dishes!",
  ui_story_5060_50600101_73_dialog_content = "Learning to make new dishes always makes me wonder what her expression will look like when I serve them to her...",
  ui_story_5060_50600101_74_dialog_content = "(Alright, I'm going to learn a bunch of recipes that Kobayashi might like, and test them out when I get back!)",
  ui_story_5060_50600101_75_dialog_content = "Boss, we're back!",
  ui_story_5060_50600101_76_dialog_content = "Good to see you guys return safely. So, did you find any <color=#FFB400>Aurorians with dragon traits</color> that Miss Tohru mentioned?",
  ui_story_5060_50600101_77_dialog_content = "Nope, no leads in that. As for the new business...",
  ui_story_5060_50600101_78_dialog_content = "You mean the delivery service, right? Don't rush; take your time.",
  ui_story_5060_50600101_79_dialog_content = "The guy in charge of the new business quit again, claiming that offering delivery services in Astra would be too risky.",
  ui_story_5060_50600101_80_dialog_content = "So, we had to get somebody else to fill in.",
  ui_story_5060_50600101_81_dialog_content = "I get it. After all, the <color=#FFB400>Eclipsites</color> are quite active. They may disrupt trade routes at any moment.",
  ui_story_5060_50600101_82_dialog_content = "Maybe we need to hire professionals like members of the Courier Union to handle it...",
  ui_story_5060_50600101_83_dialog_content = "I've been wanting to ask, but are \"<color=#FFB400>Eclipsites</color>\" some kind of monsters?",
  ui_story_5060_50600101_84_dialog_content = "Whenever people mention them, their faces turn pale.",
  ui_story_5060_50600101_85_dialog_content = "Tohru, you don't know about Eclipsites?!",
  ui_story_5060_50600101_86_dialog_content = "Well, I do come from a really far-away place, you know.",
  ui_story_5060_50600101_87_dialog_content = "Can't imagine just how far away it needs to be to stay clear of Eclipsites.",
  ui_story_5060_50600101_88_dialog_content = "Eclipsites have been part of this world since we Aurorians established our own history.",
  ui_story_5060_50600101_89_dialog_content = "They have hideous looks and savage strength, often traveling in groups, wreaking havoc in the countryside.",
  ui_story_5060_50600101_90_dialog_content = "Sometimes, under the command of powerful leaders, they even attack cities and sow chaos.",
  ui_story_5060_50600101_91_dialog_content = "It seems living in this world isn't as easy as it looks.",
  ui_story_5060_50600101_92_dialog_content = "Haha, but we've all gotten used to it. Chin up, and we can still get by.",
  ui_story_5060_50600101_93_dialog_content = "Now, let's discuss how we can help Miss Tohru find her way home!",
  ui_story_5060_50600101_94_dialog_content = "Thank you, everyone. To be honest, I know the way back home, but I ran into a slight problem...",
  ui_story_5060_50600101_95_dialog_content = "(The <color=#FFB400>mana</color> levels in this world are too unstable for the portal to activate properly...)",
  ui_story_5060_50600101_96_dialog_content = "(Right now, I need to find a location where the mana levels are relatively balanced, so I can test the portal without any interference...)",
  ui_story_5060_50600101_97_dialog_content = "(But I can't just leave Kanna and the others stuck in this world...)",
  ui_story_5060_50600101_98_dialog_content = "(I need money if I want to travel around and gather information too. Can't just keep relying on Mr. Liu's generosity...)",
  ui_story_5060_50600101_99_dialog_content = "Ahh, how stressful! This must be how Kobayashi usually feels as the head of our household!",
  ui_story_5060_50600101_100_dialog_content = "Boss, bad news! The new delivery order was once again not completed!",
  ui_story_5060_50600101_101_dialog_content = "What's the reason this time?",
  ui_story_5060_50600101_102_dialog_content = "According to our delivery guy, the customer in Umbraton was abducted by the Guild's goons...",
  ui_story_5060_50600101_103_dialog_content = "Huh?!",
  ui_story_5060_50600101_104_dialog_content = "Last time, the bridge in front of the customer's house was wrecked by the Eclipsites...",
  ui_story_5060_50600101_105_dialog_content = "And the time before that, the customer went missing in the Secret Territory... No way we can keep our business like this.",
  ui_story_5060_50600101_106_dialog_content = "(Delivery service? That might be my chance to explore my surroundings and make money at the same time!)",
  ui_story_5060_50600101_107_dialog_content = "Mr. Liu! How about I take over the delivery job and handle the rest of those undelivered orders?",
  ui_story_5060_50600101_108_dialog_content = "As long as I take things seriously, monsters and thugs don't stand a chance against me!",
  ui_story_5060_50600101_109_dialog_content = "(This would be the perfect way for me to make money and learn about this world while I search for Kanna and the others.)",
  ui_story_5060_50600101_110_dialog_content = "However, Miss Tohru, you should know that Eclipsites are frequently roaming outside the city, and our restaurant has no better means of transportation than a motorcycle...",
  ui_story_5060_50600101_111_dialog_content = "Wouldn't it make more sense to seek help from winged couriers...",
  ui_story_5060_50600101_112_dialog_content = "Well if we're talking about wings, I happen to have those too!",
  ui_story_5060_50600101_113_dialog_content = "Being able to fly is an essential skill for a professional maid. Now watch this... Oof!",
  ui_story_5060_50600101_114_dialog_content = "S-Sorry, it looks like I might have eaten too much when I first got here.",
  ui_story_5060_50600101_115_dialog_content = "Then I'll be going now!",
  ui_story_5060_50600101_116_dialog_content = "Miss Tohru, if you want to avoid unnecessary attention, it's best not to overuse those special abilities of demi-humans here...",
  ui_story_5060_50600101_117_dialog_content = "It's okay to take it slow, you know. Safety comes first!",
  ui_story_5060_50600101_118_dialog_content = "Tohru! Good luck out there!",
  ui_story_5060_50600101_119_dialog_content = "Understood! I'll be sure to complete every order and bring back plenty of positive reviews! Just leave it to me—",
  ui_story_5060_50600101_120_dialog_content = "Here I come, Astra!",
  ui_story_5060_50600101_121_dialog_content = "This Dragon Maid delivery girl is going all out!",
  ui_story_5060_50600201_1_dialog_content = "Listen up, all of you! If you don't hand over the <color=#FFB400>collection</color> now, the Caelestites will truly face extinction!",
  ui_story_5060_50600201_2_dialog_content = "That's right! They'll really be extinct!",
  ui_story_5060_50600201_3_dialog_content = "Bah, bastards! How dare you take someone as defenseless as PlayerName for a hostage?!",
  ui_story_5060_50600201_4_dialog_content = "Fight me one on one, you cowards!",
  ui_story_5060_50600201_5_dialog_content = "That's right, Kobayashi says people should fight fair in a duel.",
  ui_story_5060_50600201_6_dialog_content = "So fight me one on one, you cowards!",
  ui_story_5060_50600201_7_dialog_content = "Well said, <color=#FFB400>Kanna</color>! Ready for a fight?",
  ui_story_5060_50600201_8_dialog_content = "Yes. Thanks to Tessa, my energy is fully recharged.",
  ui_story_5060_50600201_9_dialog_content = "Ha—",
  ui_story_5060_50600201_10_dialog_content = "Hold on, didn't you agree to a one-on-one fight? Are you going to electrocute the hostage as well!?",
  ui_story_5060_50600201_11_dialog_content = "I don't mind it at all, actually!",
  ui_story_5060_50600201_12_dialog_content = "I've survived crash-landings, drenching rain, psychic attacks, wrench-related injuries, and even having foreign objects inserted into my body...",
  ui_story_5060_50600201_13_dialog_content = "After experiencing all of that, you really think I'm afraid of a little electrocution?!",
  ui_story_5060_50600201_14_dialog_content = "What? Are Caelestites always so out-of-line?",
  ui_story_5060_50600201_15_dialog_content = "Heh. The way you guys are right now, you couldn't put a scratch on any Caelestite. Besides...",
  ui_story_5060_50600201_16_dialog_content = "We never stole the <color=#FFB400>collection</color> you're talking about. This has to be some kind of misunderstanding.",
  ui_story_5060_50600201_17_dialog_content = "So just give it up already. You guys have to eat too, right? If we keep this up, my take-out is going to get cold.",
  ui_story_5060_50600201_18_dialog_content = "B-But... you were the only ones present when that thing went missing! Who else should we suspect?!",
  ui_story_5060_50600201_19_dialog_content = "Or, you know... you could just offer to pay for it.",
  ui_story_5060_50600201_20_dialog_content = "Then I'm terribly sorry—",
  ui_story_5060_50600201_21_dialog_content = "<size=45>I'm not paying a single Nightium. Don't even think about it!</size>",
  ui_story_5060_50600201_22_dialog_content = "What should we do, boss? I can't take on any of these guys by myself, and neither can we just back down like this...",
  ui_story_5060_50600201_23_dialog_content = "You worthless idiot! Of course we can't back down now. That thing matters a lot to our lords...",
  ui_story_5060_50600201_24_dialog_content = "It was stolen by that demi-human Aurorian who looks younger than ten years old!",
  ui_story_5060_50600201_25_dialog_content = "So now you're putting this on a little girl? You really have no shame.",
  ui_story_5060_50600201_26_dialog_content = "Looks like I'll have to teach you a lesson the hard way, after all.",
  ui_story_5060_50600201_27_dialog_content = "?",
  ui_story_5060_50600201_28_dialog_content = "Don't listen to those bad people or their lies, Kanna.",
  ui_story_5060_50600201_29_dialog_content = "Once we take them out, I'll share one of my lollipops with you.",
  ui_story_5060_50600201_30_dialog_content = "It's getting closer.",
  ui_story_5060_50600201_31_dialog_content = "<color=#e8d9bb>Buzz!</color>",
  ui_story_5060_50600201_32_dialog_content = "This feeling... It's getting closer, no doubt about it.",
  ui_story_5060_50600201_33_dialog_content = "<color=#e8d9bb>Buzz—Buzz—</color>",
  ui_story_5060_50600201_34_dialog_content = "It's here!",
  ui_story_5060_50600201_35_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5060_50600201_36_dialog_content = "That was close! I'm not too late, am I?!",
  ui_story_5060_50600201_37_dialog_content = "Now I know how Kobayashi feels when she works herself to the bone to beat the project deadlines...",
  ui_story_5060_50600201_38_dialog_content = "Ahem! Just a moment while I confirm the recipient's contact information...",
  ui_story_5060_50600201_39_dialog_content = "Hello, PlayerName! Here is your delivery order, please remember to give us a five-star review!",
  ui_story_5060_50600201_40_dialog_content = "Also, the shop is searching for a lost child with dragon horns on her head, one who can control electricity. If you have any relevant information...",
  ui_story_5060_50600201_41_dialog_content = "Tohru—! It's you, Tohru!",
  ui_story_5060_50600201_42_dialog_content = "K-Kanna?!",
  ui_story_5060_50600201_43_dialog_content = "I've been looking everywhere for you! I didn't expect to find you here!",
  ui_story_5060_50600201_44_dialog_content = "*snuggle* Tohru!",
  ui_story_5060_50600201_45_dialog_content = "I had no idea the friend you were looking for was such a beautiful lady, Kanna...",
  ui_story_5060_50600201_46_dialog_content = "Looks like we helped grant her wish after all, huh?",
  ui_story_5060_50600201_47_dialog_content = "Thank you so much for taking care of Kanna!",
  ui_story_5060_50600201_48_dialog_content = "Don't mention it!",
  ui_story_5060_50600201_49_dialog_content = "But speaking of trouble, we do have to put these thugs in their place.",
  ui_story_5060_50600201_50_dialog_content = "Damn it—the jerk actually called for backup?",
  ui_story_5060_50600201_51_dialog_content = "My... head's... spinning...",
  ui_story_5060_50600201_52_dialog_content = "Tch, I thought it was some big shot! Turns out it's just a maid!",
  ui_story_5060_50600201_53_dialog_content = "E-Eclipsites?! Who is this maid, able to get Eclipsites to come for backup?",
  ui_story_5060_50600201_54_dialog_content = "Run! Tactical backward advance!",
  ui_story_5060_50600201_55_dialog_content = "If I had to guess, Tohru drew them over here.",
  ui_story_5060_50600201_56_dialog_content = "So those are Eclipsites, huh? They've been chasing after me this whole time, but I was so worried about being late that I hardly noticed them.",
  ui_story_5060_50600201_57_dialog_content = "But now that your order has been delivered, I can deal with them right away!",
  ui_story_5060_50600201_58_dialog_content = "Huh? A bunch of different-colored lights just appeared in front of me!",
  ui_story_5060_50600201_59_dialog_content = "These must be the light trails PlayerName was talking about.",
  ui_story_5060_50600201_60_dialog_content = "If you follow certain light trails, you can wipe out the enemy in no time!",
  ui_story_5060_50600201_61_dialog_content = "I see. So that's the law of this world?",
  ui_story_5060_50600201_62_dialog_content = "It's just like a game, so it shouldn't be too difficult!",
  ui_story_5060_50600201_63_dialog_content = "Alright! Now that I know the rules, it's time to play!",
  ui_story_5060_50600201_64_dialog_content = "Tohru always gets so excited when it comes to destroying her enemies.",
  ui_story_5060_50600202_1_dialog_content = "That was incredible, Tohru! Didn't imagine you used your tail to defeat the Eclipsites!",
  ui_story_5060_50600202_2_dialog_content = "If Vice was here, she'd definitely want to make friends with you!",
  ui_story_5060_50600202_3_dialog_content = "Maintaining elegance and poise even during battle is a basic skill for any real maid!",
  ui_story_5060_50600202_4_dialog_content = "(Knocking Eclipsites into the air with your tail... can it really be considered \"elegant\"? Looks like she can teach Vice a thing or two...)",
  ui_story_5060_50600202_5_dialog_content = "Allow me to express my gratitude once again. Kanna is a very precious member of my family.",
  ui_story_5060_50600202_6_dialog_content = "I've been so worried ever since we got separated. Thank you both for your help!",
  ui_story_5060_50600202_7_dialog_content = "I don't know if we really deserve all of that...",
  ui_story_5060_50600202_8_dialog_content = "To tell the truth, we didn't do much for Kanna. You're the one who swooped in and saved the day, Miss Tohru.",
  ui_story_5060_50600202_9_dialog_content = "I can tell you two are good people, aren't you? Please don't worry, I just wanted to thank you!",
  ui_story_5060_50600202_10_dialog_content = "PlayerName and Tessa are good people.",
  ui_story_5060_50600202_11_dialog_content = "They took care of me, gave me candy, and even helped me find you.",
  ui_story_5060_50600202_12_dialog_content = "But those other guys were bad people.",
  ui_story_5060_50600202_13_dialog_content = "Actually, Tessa and I were at an underground auction when we bumped into Kanna.",
  ui_story_5060_50600202_14_dialog_content = "It wasn't exactly a place for little kids, so we went over to ask about her situation.",
  ui_story_5060_50600202_15_dialog_content = "But just as we were getting ready to escort her away, a bunch of thugs jumped out at us.",
  ui_story_5060_50600202_16_dialog_content = "Those jerks accused us of stealing the treasures they were about to put on display, the so-called \"<color=#FFB400>collection</color>.\"",
  ui_story_5060_50600202_17_dialog_content = "And that's how we all ended up here.",
  ui_story_5060_50600202_18_dialog_content = "Kanna, did you really not eat their treasure?",
  ui_story_5060_50600202_19_dialog_content = "Not at all.",
  ui_story_5060_50600202_20_dialog_content = "But the inside of the treasure's box smelled so familiar... I couldn't help but touch it...",
  ui_story_5060_50600202_21_dialog_content = "Don't feel guilty, Kanna! Those guys were a bunch of mean idiots, but you're a good girl!",
  ui_story_5060_50600202_22_dialog_content = "*snuggle* Tessa...",
  ui_story_5060_50600202_23_dialog_content = "Your electricity... Feels nice...",
  ui_story_5060_50600202_24_dialog_content = "Ah... She's nestling up in my arms again.",
  ui_story_5060_50600202_25_dialog_content = "Wh-What should I do?",
  ui_story_5060_50600202_26_dialog_content = "I'm sorry, she's not usually like this! After all, this is a strange new world for her, so it's normal for her to feel a little confused.",
  ui_story_5060_50600202_27_dialog_content = "Now, Kanna, that's not polite. If you need mana, you can eat some of mine.",
  ui_story_5060_50600202_28_dialog_content = "Your mana tastes bad.",
  ui_story_5060_50600202_29_dialog_content = "What? My mana tastes perfectly fine!",
  ui_story_5060_50600202_30_dialog_content = "Tohru... When can we go home?",
  ui_story_5060_50600202_31_dialog_content = "I want to go home too, but first we need to find a place where the mana is stable enough to activate the portal.",
  ui_story_5060_50600202_32_dialog_content = "I'm sad. I miss Saikawa.",
  ui_story_5060_50600202_33_dialog_content = "Don't worry, I'm sure we'll find a way back to that world soon.",
  ui_story_5060_50600202_34_dialog_content = "Speaking of which, I wanted to ask you about that...",
  ui_story_5060_50600202_35_dialog_content = "You mentioned it earlier, during our fight against the Eclipsites just now—That you two were from another world.",
  ui_story_5060_50600202_36_dialog_content = "You weren't joking... Were you?",
  ui_story_5060_50600202_37_dialog_content = "While it's true that your appearances are pretty similar to what we know as demi-human Aurorians...",
  ui_story_5060_50600202_38_dialog_content = "I've never seen anyone or anything absorb and unleash energy the same way as you do.",
  ui_story_5060_50600202_39_dialog_content = "That may be your case, but we really are dragons from another world!",
  ui_story_5060_50600202_40_dialog_content = "This is just like those manga.",
  ui_story_5060_50600202_41_dialog_content = "Unfortunately, we still haven't reconnected with most of our group...",
  ui_story_5060_50600202_42_dialog_content = "The main character in the manga is in big trouble now.",
  ui_story_5060_50600202_43_dialog_content = "You've been reading too much manga, Kanna.",
  ui_story_5060_50600202_44_dialog_content = "The fight's over. I'm tired.",
  ui_story_5060_50600202_45_dialog_content = "Are you in a hurry, Tohru?",
  ui_story_5060_50600202_46_dialog_content = "I am... But I still have plenty of time to deliver my next order.",
  ui_story_5060_50600202_47_dialog_content = "Then could you tell me about your world while you take a break here?",
  ui_story_5060_50600202_48_dialog_content = "It sounds like you're dying to know about the love story between Kobayashi and myself! I'd be happy to tell you all about it!",
  ui_story_5060_50600202_49_dialog_content = "It's a long story, so you'd better be ready for it!",
  ui_story_5060_50600202_50_dialog_content = "Sure. I can eat my lunch while you're at it, although I'm sure it's gotten cold by now...",
  ui_story_5060_50600202_51_dialog_content = "This is nothing! It just needs a little heat!",
  ui_story_5060_50600202_52_dialog_content = "Y-You can breathe fire?! That's rare, even in our world!",
  ui_story_5060_50600202_53_dialog_content = "Wow! The food is warm again!",
  ui_story_5060_50600202_54_dialog_content = "The temperature is just right... You must have perfect control over your flames, Tohru!",
  ui_story_5060_50600202_55_dialog_content = "Please enjoy your meals while I entertain you all with my story!",
  ui_story_5060_50600202_56_dialog_content = "<color=#e8d9bb>Tohru passionately shares the story of her meeting and bonding with a young lady named Kobayashi.</color>",
  ui_story_5060_50600202_57_dialog_content = "<color=#e8d9bb>However, according to Kanna, it appears that Tohru has incorporated many of her own subjective imaginations into the story...</color>",
  ui_story_5060_50600202_58_dialog_content = "Ah, I see.",
  ui_story_5060_50600202_59_dialog_content = "A world without Eclipsites or endless nights, where everyone lives in peace and order... I really want to see it for myself.",
  ui_story_5060_50600202_60_dialog_content = "It sounds like you're really close with Miss Kobayashi too.",
  ui_story_5060_50600202_61_dialog_content = "I'm sure she'll be worried sick if you don't find a way back to her world soon.",
  ui_story_5060_50600202_62_dialog_content = "That's right, which is why I decided to work as a delivery maid!",
  ui_story_5060_50600202_63_dialog_content = "This way, I can make money while searching for my missing friends. Once everyone's back together again, we can focus our efforts on finding a way home!",
  ui_story_5060_50600202_64_dialog_content = "Wait... Maybe if Kobayashi sees me after going missing for three days, she might... Heeheehee...",
  ui_story_5060_50600202_65_dialog_content = "No dirty thoughts, Tohru.",
  ui_story_5060_50600202_66_dialog_content = "Still, I miss Kobayashi too.",
  ui_story_5060_50600202_67_dialog_content = "So aside from finding your friends, you also need to find a special place for your portal to work, right?",
  ui_story_5060_50600202_68_dialog_content = "If so, I suggest you go with PlayerName to see the Cloudrover Guild.",
  ui_story_5060_50600202_69_dialog_content = "One of the most professional information brokers in all of Astra is there. She might be able to help you out.",
  ui_story_5060_50600202_70_dialog_content = "Huh? Aren't you coming along, Tessa?",
  ui_story_5060_50600202_71_dialog_content = "Don't forget, we came here on an escort job for the auction.",
  ui_story_5060_50600202_72_dialog_content = "Now that we're done, one of us needs to report back or we'll have done it for nothing.",
  ui_story_5060_50600202_73_dialog_content = "Wow, how could I almost forget... I'll be counting on you then, Tessa!",
  ui_story_5060_50600202_74_dialog_content = "Follow me, you two! I happen to be on pretty good terms with the leader of the Cloudrover Guild.",
  ui_story_5060_50600202_75_dialog_content = "The Cloudrover Guild... That name sounds familiar, but where have I heard it before...?",
  ui_story_5060_50600202_76_dialog_content = "Eh?! Isn't that where my next order needs to be delivered?!",
  ui_story_5060_50600202_77_dialog_content = "And the reason it wasn't delivered last time...",
  ui_story_5060_50600202_78_dialog_content = "Was because the recipient was too busy fighting off a bunch of gangsters!",
  ui_story_5060_50600301_1_dialog_content = "Is this the same Cloudrover Guild?!",
  ui_story_5060_50600301_2_dialog_content = "Let me take a look at their name one more time... \"<color=#FFB400>A Very Important Assistant</color>\"?",
  ui_story_5060_50600301_3_dialog_content = "Lady Sheol, Lady Sheol! Are you here?",
  ui_story_5060_50600301_4_dialog_content = "The guild's so quiet right now... Wait, what's this?!",
  ui_story_5060_50600301_5_dialog_content = "The filing cabinet has been forced open. The intelligence documents and bills are all over the ground. Could they have gotten robbed?",
  ui_story_5060_50600301_6_dialog_content = "If so, that means our customer is most likely in trouble!",
  ui_story_5060_50600301_7_dialog_content = "I expected something like this, so just leave it to me! I happen to be an expert when it comes to punishing evildoers!",
  ui_story_5060_50600301_8_dialog_content = "But you used to be the worst of the worst.",
  ui_story_5060_50600301_9_dialog_content = "Honestly, Kanna, don't say things like that! It's not nice!",
  ui_story_5060_50600301_10_dialog_content = "Hey, folks, you're here to see our boss, I presume?",
  ui_story_5060_50600301_11_dialog_content = "I'm afraid our boss has been tied up with work lately and can't meet visitors in person. If you have any questions, please speak with our new assistant.",
  ui_story_5060_50600301_12_dialog_content = "Lady Sheol isn't here? And she also hired a new assistant?",
  ui_story_5060_50600301_13_dialog_content = "Could this person be the \"Very Important Assistant\" who ordered this food?",
  ui_story_5060_50600301_14_dialog_content = "If she is, could you please tell her that the restaurant's delivery maid has arrived with her order?",
  ui_story_5060_50600301_15_dialog_content = "Besides, PlayerName and I would also like to ask this guild a few questions, if that's acceptable...",
  ui_story_5060_50600301_16_dialog_content = "I see. This takeout was ordered by the assistant and the others specifically for our boss, who was too busy with work.",
  ui_story_5060_50600301_17_dialog_content = "Unfortunately, our guild is currently dealing with a minor issue. I'm afraid we don't have the time to savor your restaurant's delicacies right now.",
  ui_story_5060_50600301_18_dialog_content = "I'll receive the takeout on behalf of our boss and settle the bill.",
  ui_story_5060_50600301_19_dialog_content = "You see, the guild is currently dealing with...",
  ui_story_5060_50600301_20_dialog_content = "You must be the famous PlayerName, our Caelestite partner, right?",
  ui_story_5060_50600301_21_dialog_content = "The famous...",
  ui_story_5060_50600301_22_dialog_content = "Caelestite...?",
  ui_story_5060_50600301_23_dialog_content = "P-Please don't call me that! You're embarrassing me in front of my new friends!",
  ui_story_5060_50600301_24_dialog_content = "I understand. Sorry if this is causing any inconvenience.",
  ui_story_5060_50600301_25_dialog_content = "As it happens, we have some internal affairs to discuss with you, PlayerName. Would you mind joining us outside?",
  ui_story_5060_50600301_26_dialog_content = "You two lovely ladies, please wait in the reception lounge for a bit.",
  ui_story_5060_50600301_27_dialog_content = "What—We have to wait?",
  ui_story_5060_50600301_28_dialog_content = "I wonder if the two of you would be interested in enjoying our specialty items during your wait?",
  ui_story_5060_50600301_29_dialog_content = "Our Cloudrover Guild has collected various exotic treasures from the Illumina Undercities, Rediesel Desert, Northland Court, and more...",
  ui_story_5060_50600301_30_dialog_content = "Wow, so many cute and pretty—",
  ui_story_5060_50600301_31_dialog_content = "If you find any treasures that catch your eye, we'd be more than willing to offer them at a discounted rate, as a token of our friendship.",
  ui_story_5060_50600301_32_dialog_content = "But I don't have any money.",
  ui_story_5060_50600301_33_dialog_content = "Ahem! You know, Kanna, I already got paid for my work. It wouldn't hurt to spend a little of it...",
  ui_story_5060_50600301_34_dialog_content = "Really? You're the best, Tohru!",
  ui_story_5060_50600301_35_dialog_content = "So what exactly happened to the guild? It seems pretty serious.",
  ui_story_5060_50600301_36_dialog_content = "Have you caught wind of the sizzling underground auction in Umbraton and Lower Lumopolis recently?",
  ui_story_5060_50600301_37_dialog_content = "As one of Astra's most renowned guilds, our Cloudrover Guild also happens to be a big sponsor for the auction.",
  ui_story_5060_50600301_38_dialog_content = "But lately, things have gone haywire at the auction, with folks insisting that their showcased items were stolen.",
  ui_story_5060_50600301_39_dialog_content = "They're making unfounded accusations and picking fights with other attendees, causing total mayhem.",
  ui_story_5060_50600301_40_dialog_content = "Lady Sheol is now working hard to resolve this matter.",
  ui_story_5060_50600301_41_dialog_content = "Oh... That's...",
  ui_story_5060_50600301_42_dialog_content = "Those troublemakers even barged into our Guild, causing the commotion you just witnessed.",
  ui_story_5060_50600301_43_dialog_content = "We've put so much effort into transporting the auction exhibits, and now they've disappeared. Shouldn't you, the Cloudrover Guild, be held accountable?",
  ui_story_5060_50600301_44_dialog_content = "The collection got stolen under your watch, so you get to pay for it!",
  ui_story_5060_50600301_45_dialog_content = "Otherwise, the lord from Lumopolis who hired us won't forgive you!",
  ui_story_5060_50600301_46_dialog_content = "That's right. I suggest all you members from the Cloudrover Guild cooperate with our investigation and not go against our lord.",
  ui_story_5060_50600301_47_dialog_content = "So even the private soldiers working for Lumopolis' nobles are in on it too, huh? How disgusting.",
  ui_story_5060_50600301_48_dialog_content = "Rare collections often get pre-booked by influential nobles; it's a common routine.",
  ui_story_5060_50600301_49_dialog_content = "To them, bidding is merely a show of their power and status.",
  ui_story_5060_50600301_50_dialog_content = "However, what might irritate them slightly would become a real burden for us merchants.",
  ui_story_5060_50600301_51_dialog_content = "If it weren't for the boss's foresight in bringing in a capable assistant to deal with them, we would be overwhelmed.",
  ui_story_5060_50600301_52_dialog_content = "So how is Lady Sheol planning on dealing with this?",
  ui_story_5060_50600301_53_dialog_content = "She suspects these items disappeared from the crates well before they reached the auction site.",
  ui_story_5060_50600301_54_dialog_content = "That's why she's hoping that you, who share a close bond with her, can lend a hand on this matter.",
  ui_story_5060_50600301_55_dialog_content = "Try using your psychic abilities as a Caelestite to see if you can trace any clues to the missing items and confirm her suspicions.",
  ui_story_5060_50600301_56_dialog_content = "... Then I'm sorry to disappoint you all...",
  ui_story_5060_50600301_57_dialog_content = "Actually, I was one of the guests who got accosted at the auction earlier...",
  ui_story_5060_50600301_58_dialog_content = "To clear up the air, I tried using my psychic abilities to search for clues, but I didn't find anything.",
  ui_story_5060_50600301_59_dialog_content = "I'm afraid the crate containing the collection really is empty!",
  ui_story_5060_50600301_60_dialog_content = "What a pity. Looks like we'll have to count on the assistant to keep those folks occupied.",
  ui_story_5060_50600301_61_dialog_content = "If you could help us sort this out, our boss will surely express her gratitude.",
  ui_story_5060_50600301_62_dialog_content = "Sheol's gratitude, huh...",
  ui_story_5060_50600301_63_dialog_content = "You were a great help to me, my friend...",
  ui_story_5060_50600301_64_dialog_content = "It looks like I need to raise you up a notch or two in my estimations.",
  ui_story_5060_50600301_65_dialog_content = "Now tell me, how should I properly compensate you for your troubles...?",
  ui_story_5060_50600301_66_dialog_content = "... I-I don't mind helping, but I'll pass on Lady Sheol's gratitude! I really can't handle any more of that!!",
  ui_story_5060_50600301_67_dialog_content = "Hmm, I think I'll pass.",
  ui_story_5060_50600301_68_dialog_content = "Huh? Who's voice is that?",
  ui_story_5060_50600301_69_dialog_content = "Assistant <color=#FFB400>Lucoa</color>!",
  ui_story_5060_50600301_70_dialog_content = "(Wait, this super-mature lady is the assistant we were talking about before?!)",
  ui_story_5060_50600301_71_dialog_content = "(She does give off a similar vibe to Lady Sheol... But she seems a lot more friendly.)",
  ui_story_5060_50600301_72_dialog_content = "Oh, you're here too? I'm really sorry, but I still have a job to do, you know!",
  ui_story_5060_50600301_73_dialog_content = "Those thugs are really dedicated to their jobs. I've been trying my best to persuade them, but they still won't break...",
  ui_story_5060_50600301_74_dialog_content = "Hey, folks, stay on your toes. This girl ain't an ordinary Aurorian... There's something seriously off about her!!",
  ui_story_5060_50600301_75_dialog_content = "I know I seem a little different, but that's no reason to be so cautious!",
  ui_story_5060_50600301_76_dialog_content = "I'm more than happy to talk things out and find a solution to this problem!",
  ui_story_5060_50600301_77_dialog_content = "Don't be fooled by her looks! Hmph, she thinks she can sweet-talk us, and we'll just walk away? It's not that easy!",
  ui_story_5060_50600301_78_dialog_content = "At the end of the day, she's just a demi-human girl, not even worthy of being a servant to the uptown lords.",
  ui_story_5060_50600301_79_dialog_content = "Let's all gang up on her, everyone. We'll surely bring her down and then use her as bargaining chips!",
  ui_story_5060_50600301_80_dialog_content = "Oh? How scary!",
  ui_story_5060_50600301_81_dialog_content = "Leave her alone, you rotten jerks—",
  ui_story_5060_50600301_82_dialog_content = "Oh my, a real knight came to my rescue! I'm so grateful!",
  ui_story_5060_50600301_83_dialog_content = "But as the guild's <color=#FFB400>Very Important Assistant</color>, I can be fairly useful in a fight too.",
  ui_story_5060_50600302_1_dialog_content = "They just keep on coming... Are you alright, Miss Lucoa?",
  ui_story_5060_50600302_2_dialog_content = "I'm perfectly fine! If anything, it must be hard for you to support me while protecting yourself, PlayerName.",
  ui_story_5060_50600302_3_dialog_content = "W-Wait, where did you learn my name?",
  ui_story_5060_50600302_4_dialog_content = "From Lady Sheol, of course! She told me so much about you...",
  ui_story_5060_50600302_5_dialog_content = "Curses! The lords' job isn't done. Get your butts up—don't you dare underestimate us!",
  ui_story_5060_50600302_6_dialog_content = "I wish you could all read the room and act appropriately.",
  ui_story_5060_50600302_7_dialog_content = "You're all way out of line... Which means I'll have to take things a little more seriously... Good little kids, remember to look away!",
  ui_story_5060_50600302_8_dialog_content = "H-Hey! Why are you covering my eyes?",
  ui_story_5060_50600302_9_dialog_content = "What?... W-w-what is this creature?! Ugh...",
  ui_story_5060_50600302_10_dialog_content = "Whew... You can look now. These guys should be a little quieter now.",
  ui_story_5060_50600302_11_dialog_content = "(Huh? Whoa... What the heck did Lucoa do to those thugs..?)",
  ui_story_5060_50600302_12_dialog_content = "(They look like they just got thrown into a pit full of high-level Eclipsites...)",
  ui_story_5060_50600302_13_dialog_content = "Let me sense around...",
  ui_story_5060_50600302_14_dialog_content = "Is this... A feather...?",
  ui_story_5060_50600302_15_dialog_content = "Ah—I said no peeking!",
  ui_story_5060_50600302_16_dialog_content = "S-Sorry! I was just curious about your power, that's all...",
  ui_story_5060_50600302_17_dialog_content = "Oh? So you're curious to see my true form?",
  ui_story_5060_50600302_18_dialog_content = "You know, you're just as cute as <color=#FFB400>Shouta</color> when I take a closer look!",
  ui_story_5060_50600302_19_dialog_content = "The face you make when you use your powers is especially cute. So this is the Caelestite I've heard so much about!",
  ui_story_5060_50600302_20_dialog_content = "Such a cute face... Would you mind if I touched it?",
  ui_story_5060_50600302_21_option_content = "Begone, demon!",
  ui_story_5060_50600302_22_dialog_content = "Boo-hoo, that really hurts. I'm not a demon at all...",
  ui_story_5060_50600302_23_dialog_content = "I'm a good person now!",
  ui_story_5060_50600302_24_dialog_content = "Anyone else would have reported you to the Lumopolis Guardians a long time ago!!",
  ui_story_5060_50600302_25_option_content = "B-But I'll get suffocated...",
  ui_story_5060_50600302_26_dialog_content = "D-Don't you have other guild business to attend to, Miss Lucoa...?",
  ui_story_5060_50600302_27_dialog_content = "This place is dangerous, after all. Who knows when those private soldiers will show up to investigate... Hahaha...",
  ui_story_5060_50600302_28_dialog_content = "To be honest, I'm less of an assistant and more of a bodyguard that Lady Sheol hired for this matter.",
  ui_story_5060_50600302_29_dialog_content = "I'm actually quite powerful and can handle most situations.",
  ui_story_5060_50600302_30_dialog_content = "After all, I happen to be a goddess in my native land...",
  ui_story_5060_50600302_31_dialog_content = "Lu—co—a—",
  ui_story_5060_50600302_32_dialog_content = "Hmm? Is that you, Tohru?",
  ui_story_5060_50600302_33_dialog_content = "I've been running myself ragged trying to find a way to reactivate the portal...",
  ui_story_5060_50600302_34_dialog_content = "Yet you're over here slacking off?!",
  ui_story_5060_50600302_35_dialog_content = "And calling yourself a \"Very Important Assistant\"...",
  ui_story_5060_50600302_36_dialog_content = "Oh my! How did you discover my alias in this world, Tohru...?",
  ui_story_5060_50600302_37_dialog_content = "Lucoa has been exposed.",
  ui_story_5060_50600302_38_dialog_content = "Ah! Don't tell me you're the one delivering my food, Tohru?",
  ui_story_5060_50600302_39_dialog_content = "A maid delivery girl... What an interesting gimmick!",
  ui_story_5060_50600302_40_dialog_content = "Ever since I realized how different the mana is in this world, I've been trying to find a way to enhance my body's ability to convert it.",
  ui_story_5060_50600302_41_dialog_content = "That way, I could use my powers to pinpoint everyone's exact location.",
  ui_story_5060_50600302_42_dialog_content = "Unfortunately, since most people here tend to use these so-called \"Luminatics\" to solve their problems...",
  ui_story_5060_50600302_43_dialog_content = "I haven't been able to find an equally talented child as Shouta to form a temporary pact with me.",
  ui_story_5060_50600302_44_dialog_content = "Thank goodness no one's been hurt so far.",
  ui_story_5060_50600302_45_dialog_content = "But I can't say I'm not interested in this Caelestite everyone keeps talking about! If anything, I have high hopes for him!",
  ui_story_5060_50600302_46_dialog_content = "Give it a rest already, Lucoa!",
  ui_story_5060_50600302_47_dialog_content = "Ahem! In any case, we managed to find Lucoa, which means we just need to find Elma and Fafnir now.",
  ui_story_5060_50600302_48_dialog_content = "Well, Lucoa? Everyone says this guild is one of the best sources of information.",
  ui_story_5060_50600302_49_dialog_content = "Have you discovered anything regarding those two?",
  ui_story_5060_50600302_50_dialog_content = "I've been paying close attention to anything related to dragons or demi-humans with dragon-like characteristics.",
  ui_story_5060_50600302_51_dialog_content = "My most recent lead involves the disappearance of a collection from an auction, which is what I'm working on right now.",
  ui_story_5060_50600302_52_dialog_content = "Huh? So you're investigating those thugs too? And it's because they have something to do with dragons?",
  ui_story_5060_50600302_53_dialog_content = "Of course. My intuition never lies, you know?",
  ui_story_5060_50600302_54_dialog_content = "Lucoa is getting serious.",
  ui_story_5060_50600302_55_dialog_content = "Most of those thugs work for a smuggling gang, and one of them accidentally mentions that the missing item is a dragon's hidden treasure.",
  ui_story_5060_50600302_56_dialog_content = "A treasure that was only obtained after risking death under a dragon's claws.",
  ui_story_5060_50600302_57_dialog_content = "Has one of us dropped something? Maybe Fafnir...?",
  ui_story_5060_50600302_58_dialog_content = "Probably not...",
  ui_story_5060_50600302_59_dialog_content = "Otherwise, they would be cursed.",
  ui_story_5060_50600302_60_dialog_content = "You have a point.",
  ui_story_5060_50600302_61_dialog_content = "Miss Lucoa, I'd like to ask you a few questions, if that's okay?",
  ui_story_5060_50600302_62_dialog_content = "Lady Sheol wanted to use my powers to locate the lost collection.",
  ui_story_5060_50600302_63_dialog_content = "But when I tried using them at the auction, I don't know if it was a lack of information or something else...",
  ui_story_5060_50600302_64_dialog_content = "My psychic powers didn't work.",
  ui_story_5060_50600302_65_dialog_content = "Could you tell me more about this missing collection? Or maybe more information on this gang of smugglers?",
  ui_story_5060_50600302_66_dialog_content = "I know what you're thinking. As a Caelestite, you need to be familiar enough with something in order to sense it with your powers, right?",
  ui_story_5060_50600302_67_dialog_content = "The smugglers in question generally work for the upper classes of both Umbraton and Lumopolis. They specialize in hunting large creatures and scouring ruins for artifacts.",
  ui_story_5060_50600302_68_dialog_content = "The items they brought for display this time were mostly specimens and hides of rare and valuable creatures.",
  ui_story_5060_50600302_69_dialog_content = "They may have even brought in a live specimen...",
  ui_story_5060_50600302_70_dialog_content = "That would explain why the top of that box felt so warm...",
  ui_story_5060_50600302_71_dialog_content = "Wait, did you stumble on a clue too, Kanna?!",
  ui_story_5060_50600302_72_dialog_content = "Well, Kanna? How did the treasure go missing?",
  ui_story_5060_50600302_73_dialog_content = "Probably... Probably because it grew legs and ran away!",
  ui_story_5060_50600302_74_dialog_content = "Err...",
  ui_story_5060_50600302_75_dialog_content = "Aside from manga, I wonder if I'm letting you read too many fairy tales too...",
  ui_story_5060_50600302_76_dialog_content = "... Still nothing. Even with Kanna and Lucoa's help, and knowing that it's a living specimen...",
  ui_story_5060_50600302_77_dialog_content = "I still have no way of sensing where it is.",
  ui_story_5060_50600302_78_dialog_content = "Don't get frustrated, PlayerName. You've already done so much.",
  ui_story_5060_50600302_79_dialog_content = "I know, but it's not every day that I can help everyone out while also winning favors from Lady Sheol. I wish I could do more...",
  ui_story_5060_50600302_80_dialog_content = "Here comes my chance.",
  ui_story_5060_50600302_81_dialog_content = "Come here, little Caelestite! Have a hug!",
  ui_story_5060_50600302_82_dialog_content = "Waaaah! L-L-Let go...!",
  ui_story_5060_50600302_83_dialog_content = "What a lukewarm reaction, PlayerName.",
  ui_story_5060_50600302_84_dialog_content = "Thanks to your influence, I have a much more comprehensive understanding of this world. In a way, it's like we share the same mind despite having separate bodies.",
  ui_story_5060_50600302_85_dialog_content = "Let me pass my power onto you!",
  ui_story_5060_50600302_86_dialog_content = "Th-That was just me using my psychic abilities earlier! I was only helping you see the light trails!",
  ui_story_5060_50600302_87_dialog_content = "Stop it, or I'll report you to Lady Sheol!",
  ui_story_5060_50600302_88_dialog_content = "Is that so? Lady Sheol and I are pretty close, you know? She even gave me something I really wanted as an advance on my salary!",
  ui_story_5060_50600302_89_dialog_content = "Unfortunately, since I've been given a tribute, I can't just do as I please anymore.",
  ui_story_5060_50600302_90_dialog_content = "Hurry Tohru, or else PlayerName might die...",
  ui_story_5060_50600302_91_dialog_content = "Ugh, honestly... You still seem to be doing whatever you want, Lucoa.",
  ui_story_5060_50600302_92_dialog_content = "If you have this much free time, why not help me deliver these orders?!",
  ui_story_5060_50600302_93_dialog_content = "Anyway, PlayerName, are you sure you want to help us?",
  ui_story_5060_50600302_94_dialog_content = "Don't you have other jobs or investigations to do?",
  ui_story_5060_50600302_95_dialog_content = "Can we go together?",
  ui_story_5060_50600302_96_dialog_content = "Don't say things like that, Kanna. PlayerName happens to be someone very important in this world.",
  ui_story_5060_50600302_97_dialog_content = "I'm sure he has plenty of equally important things to do right now.",
  ui_story_5060_50600302_98_dialog_content = "I don't, actually... And I'm really not that important, Tohru. Anyway, where is your next order going?",
  ui_story_5060_50600302_99_dialog_content = "Let me see, I think it was an outpost in someplace called \"Illumina Outpost.\"",
  ui_story_5060_50600302_100_dialog_content = "That shouldn't be a problem, then! I need to go there too!",
  ui_story_5060_50600302_101_dialog_content = "As an outpost on the borderlands, there must be plenty of smugglers operating in the area. I bet we'll find plenty of information there!",
  ui_story_5060_50600302_102_dialog_content = "Yay, we get to go on another adventure!",
  ui_story_5060_50600302_103_dialog_content = "To save us some time, why don't we fly over there?",
  ui_story_5060_50600302_104_dialog_content = "Huh? How did you know I could turn into a dragon, PlayerName? I don't remember telling you that.",
  ui_story_5060_50600302_105_dialog_content = "Huh?",
  ui_story_5060_50600302_106_dialog_content = "I meant that we can ride Soroz to Illumina Outpost. What were you talking about, Tohru?",
  ui_story_5060_50600302_107_dialog_content = "S... Sor-what?",
  ui_story_5060_50600401_1_dialog_content = "So this is Soroz, PlayerName? Your friend is so tiny...",
  ui_story_5060_50600401_2_dialog_content = "Hey! Soroz would be really upset if you confused it for a regular airship!",
  ui_story_5060_50600401_3_dialog_content = "You'll understand once get there... I bet Soroz is no smaller than any dragon you've mentioned so far.",
  ui_story_5060_50600401_4_dialog_content = "Really? I'm even more excited to see it!",
  ui_story_5060_50600401_5_dialog_content = "Still, this airship is too small to transport all of us to Soroz in one trip.",
  ui_story_5060_50600401_6_dialog_content = "You said something about being able to fly, right, Tohru?",
  ui_story_5060_50600401_7_dialog_content = "Of course! I'm a dragon, after all!",
  ui_story_5060_50600401_8_dialog_content = "So you can really fly?",
  ui_story_5060_50600401_9_dialog_content = "I want to ride the airship. It looks fun.",
  ui_story_5060_50600401_10_dialog_content = "In that case, I'll stay with Kanna.",
  ui_story_5060_50600401_11_dialog_content = "Can't you try losing a little weight, Lucoa? There's no room for my motorcycle...",
  ui_story_5060_50600401_12_dialog_content = "Hey PlayerName, can I ask you a question?",
  ui_story_5060_50600401_13_dialog_content = "Sure, what is it?",
  ui_story_5060_50600401_14_dialog_content = "What exactly are demi-human Aurorians?",
  ui_story_5060_50600401_15_dialog_content = "While I was making deliveries, I spotted some winged children flying through the sky.",
  ui_story_5060_50600401_16_dialog_content = "They seemed so comfortable and free, and they looked a lot like us right now.",
  ui_story_5060_50600401_17_dialog_content = "But the people of Lumopolis seemed to regard their horns and wings as bad things... I don't really understand why, though.",
  ui_story_5060_50600401_18_dialog_content = "Did the nobles pick on you while you were in Lumopolis too, Tohru?",
  ui_story_5060_50600401_19_dialog_content = "Not at all. Maybe it was because of my destructive aura; none of them dared to approach me.",
  ui_story_5060_50600401_20_dialog_content = "However, they made things really hard for the other demi-humans working in Mr. Liu's restaurant. I couldn't stand watching them.",
  ui_story_5060_50600401_21_dialog_content = "There are a lot of reasons involved, but their race and status are definitely the biggest ones.",
  ui_story_5060_50600401_22_dialog_content = "True demi-humans were incapable of using Luminatics, so they were wiped out a long time ago.",
  ui_story_5060_50600401_23_dialog_content = "The demi-human Aurorians we see today are the descendants of true demi-humans who intermarried with Aurorians.",
  ui_story_5060_50600401_24_dialog_content = "To Lumo Nobles, these unwanted people are nothing but a stain to their faith and their noble bloodlines.",
  ui_story_5060_50600401_25_dialog_content = "Ugh, not this again. Faith, pure bloodlines, blessings... It's because of notions like these that we see humans as a foolish and inferior species.",
  ui_story_5060_50600401_26_dialog_content = "Thankfully, Aurorians have become more and more accepting towards demi-human Aurorians these days. This trend is happening among a few Lumopolis nobles too...",
  ui_story_5060_50600401_27_dialog_content = "Oh, looks like we're almost there. We should be able to see Soroz once we pass through these clouds.",
  ui_story_5060_50600401_28_dialog_content = "Everyone, I'd like you to meet my friend Soroz!",
  ui_story_5060_50600401_29_dialog_content = "The Aurorians of this world refer to their kind as the Colossi. They're the close companions of the Caelestites, and can only be piloted by our people.",
  ui_story_5060_50600401_30_dialog_content = "Wow, it's enormous! Wait, is Soroz... A fully-mechanical dragon?!",
  ui_story_5060_50600401_31_dialog_content = "A robot dragon, just like in the movies.",
  ui_story_5060_50600401_32_dialog_content = "Something this unique must be really good in combat, right? Can I challenge him to a fight right now?!",
  ui_story_5060_50600401_33_dialog_content = "Uh... Soroz has never been in battle...",
  ui_story_5060_50600401_34_dialog_content = "What a shame.",
  ui_story_5060_50600401_35_dialog_content = "Anyway, let's just go inside.",
  ui_story_5060_50600401_36_dialog_content = "Wow—So pretty!",
  ui_story_5060_50600401_37_dialog_content = "This place too—",
  ui_story_5060_50600401_38_dialog_content = "Don't bother other people, Kanna!",
  ui_story_5060_50600401_39_dialog_content = "Not only is there plenty of room, but it's also fully equipped and tastefully decorated. Living here must be really convenient!",
  ui_story_5060_50600401_40_dialog_content = "Warning: approaching weight limit. Please avoid carrying excessive baggage.",
  ui_story_5060_50600401_41_dialog_content = "... Didn't I tell you, Lucoa? You really should try to lose some weight.",
  ui_story_5060_50600401_42_dialog_content = "Really? You mean it's not your chubby tail weighing us down?",
  ui_story_5060_50600401_43_dialog_content = "Don't worry, it's probably just a glitch in the system. Soroz is much tougher than that.",
  ui_story_5060_50600401_44_dialog_content = "It looks like you really trust this big Colossus of yours. You must have a wonderful relationship with it.",
  ui_story_5060_50600401_45_dialog_content = "Yep! After all, Soroz is one of my closest and most important friends.",
  ui_story_5060_50600401_46_dialog_content = "Over ten years ago... I lost my home, as well as all of my family.",
  ui_story_5060_50600401_47_dialog_content = "I had no choice but to accept that I was the last living Caelestite in the world.",
  ui_story_5060_50600401_48_dialog_content = "If it wasn't for Soroz keeping me company and teaching me all sorts of things, I wouldn't be where I am today.",
  ui_story_5060_50600401_49_dialog_content = "I completely understand.",
  ui_story_5060_50600401_50_dialog_content = "My relationship with Kobayashi is exactly the same. As expected, love knows no boundaries, not even between species!",
  ui_story_5060_50600401_51_dialog_content = "I-I'm not sure if it's EXACTLY the same.",
  ui_story_5060_50600401_52_dialog_content = "So you see, Tohru, I know what it's like to arrive in a strange new world, and the fear and mistrust that comes with it.",
  ui_story_5060_50600401_53_dialog_content = "But thanks to Soroz's help, as well as the help of countless friends...",
  ui_story_5060_50600401_54_dialog_content = "I don't feel so alone and powerless in the world anymore.",
  ui_story_5060_50600401_55_dialog_content = "So when I saw how desperately you wanted to reunite with your friends, my heart told me to help you in any way I could.",
  ui_story_5060_50600401_56_dialog_content = "Friends are our greatest treasure. I don't know how much longer our worlds will be connected...",
  ui_story_5060_50600401_57_dialog_content = "But even if it's only for a short while, I really hope we can all be friends, Tohru!",
  ui_story_5060_50600401_58_dialog_content = "I want to hear even more stories about the other worlds you've been to... As well as the love story between you and Miss Kobayashi!",
  ui_story_5060_50600401_59_dialog_content = "Honestly, you have some nerve saying all of that...",
  ui_story_5060_50600401_60_dialog_content = "Isn't it obvious that we're friends already?",
  ui_story_5060_50600401_61_dialog_content = "When I activated the teleportation portal, I originally meant to go back to my home world and take a few photos of it...",
  ui_story_5060_50600401_62_dialog_content = "But you know what? I think the scenery in this world is nice too!",
  ui_story_5060_50600401_63_dialog_content = "When all of this is over, let's use this camera to take a group photo, okay?",
  ui_story_5060_50600401_64_dialog_content = "... Yes! I'd like that!",
  ui_story_5060_50600401_65_dialog_content = "You seem happy, PlayerName.",
  ui_story_5060_50600401_66_dialog_content = "Remember to smile like that for the photo.",
  ui_story_5060_50600401_67_dialog_content = "Hahaha! I definitely will!",
  ui_story_5060_50600401_68_dialog_content = "<color=#e8d9bb>Some time later...</color>",
  ui_story_5060_50600401_69_dialog_content = "We're getting close to the delivery address.",
  ui_story_5060_50600401_70_dialog_content = "What exactly is the purpose of building an Illumina Outpost, PlayerName? Is it some kind of defensive structure?",
  ui_story_5060_50600401_71_dialog_content = "I guess you could say that.",
  ui_story_5060_50600401_72_dialog_content = "Sigh, the Illumina Federation really needs to revamp their meal policies if their soldiers have to order take-out to feed themselves.",
  ui_story_5060_50600401_73_dialog_content = "Out of curiosity, Tohru, what did the customer order to eat?",
  ui_story_5060_50600401_74_dialog_content = "Desserts, with a side of even more dessert. Pretty odd for a customer, huh?",
  ui_story_5060_50600401_75_dialog_content = "It's probably because they're seriously lacking in sugar out here. I can totally relate.",
  ui_story_5060_50600401_76_dialog_content = "After all, the war against Eclipsites is an extremely dangerous one. Without enough energy, they'd all be in serious trouble.",
  ui_story_5060_50600401_77_dialog_content = "Eclipsites, huh? Honestly, I don't think they're all that tough... Are they really such a huge threat to the entire world?",
  ui_story_5060_50600401_78_dialog_content = "Compared to those Eclipsites just now, you and your friends are insanely powerful.",
  ui_story_5060_50600401_79_dialog_content = "But in the wild, these monsters don't attack in packs, but in huge waves.",
  ui_story_5060_50600401_80_dialog_content = "Our battle against the Eclipsites is one that has never ended.",
  ui_story_5060_50600401_81_dialog_content = "In a way, Astra's history is a history of our struggles against the Eclipsites.",
  ui_story_5060_50600401_82_dialog_content = "You really can't afford to drop your guard in this world, huh?",
  ui_story_5060_50600401_83_dialog_content = "Look, smoke!",
  ui_story_5060_50600401_84_dialog_content = "Tohru, PlayerName, look down there! The Eclipsites are attacking a village!",
  ui_story_5060_50600401_85_dialog_content = "I see it! Just give me a minute, and I'll find a spot to land!",
  ui_story_5060_50600401_86_dialog_content = "If too many Eclipsites attack, the Illumina outpost might not be able to hold them off.",
  ui_story_5060_50600401_87_dialog_content = "Lots of people are hurt.",
  ui_story_5060_50600401_88_dialog_content = "I want to help them...",
  ui_story_5060_50600401_89_dialog_content = "These people live such difficult lives. All of them look so tired and afraid.",
  ui_story_5060_50600401_90_dialog_content = "Yes, and you can tell that some of them came from even more distant and less-defended areas of the Illumina Federation.",
  ui_story_5060_50600401_91_dialog_content = "Um...",
  ui_story_5060_50600401_92_dialog_content = "Huh? No!",
  ui_story_5060_50600401_93_dialog_content = "...",
  ui_story_5060_50600401_94_dialog_content = "I-I wanted to help her, but she ran away.",
  ui_story_5060_50600401_95_dialog_content = "My guess is that after experiencing so much destruction just now, these people don't have the strength to deal with strangers.",
  ui_story_5060_50600401_96_dialog_content = "We should just leave some food for them here, and give them plenty of space to calm down.",
  ui_story_5060_50600401_97_dialog_content = "This doesn't really look like the time to be delivering take-out orders...",
  ui_story_5060_50600401_98_dialog_content = "Hey! Listen up, you rotten Eclipsites!",
  ui_story_5060_50600401_99_dialog_content = "If I get reported for being late, you can kiss your home world goodbye! If you understand what I'm saying, then—",
  ui_story_5060_50600401_100_dialog_content = "... Are these guys really incapable of communicating?",
  ui_story_5060_50600401_101_dialog_content = "Guess I have no choice... But to break the rules of this world a little bit.",
  ui_story_5060_50600501_1_dialog_content = "So many Eclipsites...",
  ui_story_5060_50600501_2_dialog_content = "What a pain! They really do attack in waves!",
  ui_story_5060_50600501_3_dialog_content = "If there weren't Illumina Federation people scattered among them, I could fry them all with my Dragon Breath...",
  ui_story_5060_50600501_4_dialog_content = "Do your best, everyone! I'll work hard to provide moral support too!",
  ui_story_5060_50600501_5_dialog_content = "Get over here and help us!",
  ui_story_5060_50600501_6_dialog_content = "They must have built a nest somewhere nearby. We won't get anywhere unless we find it quickly and destroy it.",
  ui_story_5060_50600501_7_dialog_content = "Leave that to me! Once I switch into my dragon form...",
  ui_story_5060_50600501_8_dialog_content = "<size=45>Everyone!</size>",
  ui_story_5060_50600501_9_dialog_content = "The Illumina soldiers and I just finished destroying the nest up ahead!",
  ui_story_5060_50600501_10_dialog_content = "Hold the line and finish off the rest of the enemy's forces!",
  ui_story_5060_50600501_11_dialog_content = "Let every wicked remnant be crushed by the might of order!",
  ui_story_5060_50600501_12_dialog_content = "It's the deputy Captain <color=#FFB400>Elma</color>!",
  ui_story_5060_50600501_13_dialog_content = "Captain Elma looks so sharp!",
  ui_story_5060_50600501_14_dialog_content = "(Damn it, I'm starving! Why hasn't my food been delivered yet?!)",
  ui_story_5060_50600501_15_dialog_content = "(If this food tastes bad, I'm definitely leaving them a one-star review!)",
  ui_story_5060_50600502_1_dialog_content = "Phew... They're all gone now. Time to recharge.",
  ui_story_5060_50600502_2_dialog_content = "Um...",
  ui_story_5060_50600502_3_dialog_content = "Hey, it's the girl who ran away from me just now.",
  ui_story_5060_50600502_4_dialog_content = "I'm sorry for before... I was just so scared...",
  ui_story_5060_50600502_5_dialog_content = "That's why I ran away... It's absolutely, absolutely not because I dislike you.",
  ui_story_5060_50600502_6_dialog_content = "The battle just now... it was really amazing!",
  ui_story_5060_50600502_7_dialog_content = "You seem around my age, but... you're really dashing, sharp, and cool!",
  ui_story_5060_50600502_8_dialog_content = "I'd like to present this flower to you!",
  ui_story_5060_50600502_9_dialog_content = "Oh, she ran away again.",
  ui_story_5060_50600502_10_dialog_content = "But it looks like this time she ran away out of shyness instead of fear.",
  ui_story_5060_50600502_11_dialog_content = "I think you just made a new friend in this world, Kanna!",
  ui_story_5060_50600502_12_dialog_content = "A friend...?",
  ui_story_5060_50600502_13_dialog_content = "Will she always be watching me?",
  ui_story_5060_50600502_14_dialog_content = "Hahaha, I'm sure she will! See, even though she's hiding behind that rock over there, she's still looking at you!",
  ui_story_5060_50600502_15_dialog_content = "I'm done recharging now.",
  ui_story_5060_50600502_16_dialog_content = "Good! Now that the Eclipsites are taken care of, it's time to deliver this order to its rightful owner.",
  ui_story_5060_50600502_17_dialog_content = "You know, running into her as a delivery girl in this world really is a twist of fate.",
  ui_story_5060_50600502_18_dialog_content = "The way you said that... Do you know the person who placed the order, Tohru? I thought it was someone from the Illumina Federation?",
  ui_story_5060_50600502_19_dialog_content = "No, she's definitely one of ours. No one else would place an order like this.",
  ui_story_5060_50600502_20_dialog_content = "Isn't that right, Elma?",
  ui_story_5060_50600502_21_dialog_content = "My desserts! They finally showed up!!!",
  ui_story_5060_50600502_22_dialog_content = "Huh? Tohru?! What are you doing here?!",
  ui_story_5060_50600502_23_dialog_content = "Were you going to eat all of those before talking to me...?",
  ui_story_5060_50600502_24_dialog_content = "I came to deliver your food!",
  ui_story_5060_50600502_25_dialog_content = "I had to pick up a job in this world just to make money and look for any clues regarding your whereabouts, you know...",
  ui_story_5060_50600502_26_dialog_content = "... And judging from the size of this order, you probably ordered one of everything from Mr. Liu's dessert menu, didn't you?!",
  ui_story_5060_50600502_27_dialog_content = "I couldn't help it! I nearly starved to death when we arrived in this world!",
  ui_story_5060_50600502_28_dialog_content = "It wasn't easy, but I managed to use my clairvoyance to find a little bird with a flyer tied to its leg...",
  ui_story_5060_50600502_29_dialog_content = "And everything on the menu looked so delicious!",
  ui_story_5060_50600502_30_dialog_content = "So I checked every single box on the dessert menu and made a dipping sauce out of Eclipsite fluids!",
  ui_story_5060_50600502_31_dialog_content = "After that, I tied the menu back on the birdie's leg and let it fly away!",
  ui_story_5060_50600502_32_dialog_content = "But then I started to get really hungry again as more Eclipsites attacked us. I was worried that I wasn't able to place my order correctly since my food had never arrived.",
  ui_story_5060_50600502_33_dialog_content = "But in the end, it showed up right on time! Heeheehee!",
  ui_story_5060_50600502_34_dialog_content = "I see. In that case—",
  ui_story_5060_50600502_35_dialog_content = "Thank you for your business! If you enjoy the food, please remember to give us a five-star rating!",
  ui_story_5060_50600502_36_dialog_content = "Here's the bill for the food plus delivery!",
  ui_story_5060_50600502_37_dialog_content = "Huh? What did you say?",
  ui_story_5060_50600502_38_dialog_content = "<size=45>Here's the bill for the food plus delivery!</size>",
  ui_story_5060_50600502_39_dialog_content = "... D-Do you accept Japanese yen, by any chance...?",
  ui_story_5060_50600502_40_dialog_content = "Don't be silly, dear customer! Our shop only accepts Nightium, as you surely know!",
  ui_story_5060_50600502_41_dialog_content = "So hand over—all of—your Nightium—",
  ui_story_5060_50600502_42_dialog_content = "... You're being too scary!",
  ui_story_5060_50600502_43_dialog_content = "I'll cover the Deputy Captain's bill. After all, she saved our lives.",
  ui_story_5060_50600502_44_dialog_content = "Count me in! The Deputy Captain's strength is worth more than a few Nightium!",
  ui_story_5060_50600502_45_dialog_content = "*sniffle* I... I'm so touched, everyone!",
  ui_story_5060_50600502_46_dialog_content = "Let's rest and regroup for now, so we can attack the Eclipsites' main camp! We'll exterminate every last one of them!",
  ui_story_5060_50600502_47_dialog_content = "Splendor Illumina!!",
  ui_story_5060_50600502_48_dialog_content = "...",
  ui_story_5060_50600502_49_dialog_content = "PlayerName is too stunned to speak.",
  ui_story_5060_50600502_50_dialog_content = "You're just as ridiculous as ever, Elma.",
  ui_story_5060_50600502_51_dialog_content = "As a law-abiding dragon of the Harmony Faction, I'm surprised you're also fulfilling your responsibilities in this world.",
  ui_story_5060_50600502_52_dialog_content = "I-I have a good reason for that... And you're one to talk, Tohru!",
  ui_story_5060_50600502_53_dialog_content = "Just look at you... A dragon maid delivering eastern food on a motorcycle...",
  ui_story_5060_50600502_54_dialog_content = "You're not acting like a dragon of the Chaos Faction at all!",
  ui_story_5060_50600502_55_dialog_content = "Like I said, I'm only doing this to find all of you so we can go back home sooner!",
  ui_story_5060_50600502_56_dialog_content = "Tohru and Elma are like fire and water, just like always.",
  ui_story_5060_50600502_57_dialog_content = "Heheheh, you still don't understand the feelings between old enemies, Kanna.",
  ui_story_5060_50600502_58_dialog_content = "You two may look like you're arguing, but you don't actually hate each other, do you? In fact, you probably understand each other really well!",
  ui_story_5060_50600502_59_dialog_content = "Now that the battle is over and everyone from the Illumina Federation is going back...",
  ui_story_5060_50600502_60_dialog_content = "Why don't we sit down and eat first? Then we can talk about looking for more information around here.",
  ui_story_5060_50600502_61_dialog_content = "Everyone's hungry, and the only one who ate was Elma...",
  ui_story_5060_50600502_62_dialog_content = "... But I'm sure she can eat another meal.",
  ui_story_5060_50600502_63_dialog_content = "Alright, count me in! Let's celebrate our victory with a nice, big feast!",
  ui_story_5060_50600502_64_dialog_content = "It smells so good!",
  ui_story_5060_50600502_65_dialog_content = "This food is incredible! I can feel my power coming back to me!",
  ui_story_5060_50600502_66_dialog_content = "Hahaha, I'm glad you like it! A friend taught me how to make this a while ago.",
  ui_story_5060_50600502_67_dialog_content = "As expected, we Aurorians and Caelestites are the perfect partners!",
  ui_story_5060_50600502_68_dialog_content = "But you're a dragon.",
  ui_story_5060_50600502_69_dialog_content = "Everyone here keeps saying that, but I don't worry about small details like that!",
  ui_story_5060_50600502_70_dialog_content = "Sigh, what are we gonna do with you...",
  ui_story_5060_50600502_71_dialog_content = "I brought some of Mr. Liu's steamed buns too. Try one, everybody!",
  ui_story_5060_50600502_72_dialog_content = "Save some for me, Tohru!",
  ui_story_5060_50600502_73_dialog_content = "Kanna said something about you two being like water and fire, didn't she?",
  ui_story_5060_50600502_74_dialog_content = "People don't usually describe friends that way. What's the story between you two?",
  ui_story_5060_50600502_75_dialog_content = "I suppose you can say we're friends now, but we used to be mortal enemies.",
  ui_story_5060_50600502_76_dialog_content = "I'm a dragon of the Chaos Faction, while she belongs to the Harmony Faction.",
  ui_story_5060_50600502_77_dialog_content = "It's kind of hard to imagine that you two were enemies just because of your factions.",
  ui_story_5060_50600502_78_dialog_content = "Conflict is bound to exist in any world, after all.",
  ui_story_5060_50600502_79_dialog_content = "In the world we come from...",
  ui_story_5060_50600502_80_dialog_content = "We may not have to contend with disgusting creatures like Eclipsites every day, like in your world...",
  ui_story_5060_50600502_81_dialog_content = "There will always be creatures with differing viewpoints. Naturally, the same is true for dragons who refuse to get along.",
  ui_story_5060_50600502_82_dialog_content = "But I still want to believe what Kobayashi told me—",
  ui_story_5060_50600502_83_dialog_content = "That if everyone is willing to communicate and treat each other like allies, then there wouldn't be any more strife in the world.",
  ui_story_5060_50600502_84_dialog_content = "Just like when we mix your cooking with Mr. Liu's steamed buns, it makes everything taste twice as delicious!",
  ui_story_5060_50600502_85_dialog_content = "I think Elma's going to eat everything herself.",
  ui_story_5060_50600502_86_dialog_content = "Hahaha, I agree. The Deputy Captain's metaphors are pretty peculiar indeed.",
  ui_story_5060_50600502_87_dialog_content = "I remember when I first met the Deputy Captain; she used to be a bit reserved, talking about etiquette and rules all the time.",
  ui_story_5060_50600502_88_dialog_content = "Now, she's become an excellent outpost soldier! Being a bit odd is no big deal.",
  ui_story_5060_50600502_89_dialog_content = "It's strange, but ever since we reunited with each other, Elma hasn't told me anything about disrupting the world's order...",
  ui_story_5060_50600502_90_dialog_content = "Or to go back to where I belong.",
  ui_story_5060_50600502_91_dialog_content = "She hasn't leveled any mountains or destroyed people's houses in the name of maintaining order, either.",
  ui_story_5060_50600502_92_dialog_content = "Stop trying to stir the pot, Tohru...",
  ui_story_5060_50600502_93_dialog_content = "Alright, Deputy Captain, I've got some candy here.",
  ui_story_5060_50600502_94_dialog_content = "I know you have a sweet tooth, so these are all for you.",
  ui_story_5060_50600502_95_dialog_content = "Oh, you guys are the best! I'm so glad I found a job like this in your world...",
  ui_story_5060_50600502_96_dialog_content = "You guys will always be my friends!",
  ui_story_5060_50600502_97_dialog_content = "You're making friends a little too casually, don't you think?",
  ui_story_5060_50600502_98_dialog_content = "Honestly, how do you manage to integrate into whatever environment you find yourself in?",
  ui_story_5060_50600502_99_dialog_content = "Does everyone in the Harmony Faction have this gift?",
  ui_story_5060_50600601_1_dialog_content = "We've come across those criminals PlayerName mentioned! They came here from the Rediesel Desert.",
  ui_story_5060_50600601_2_dialog_content = "At that time, we found out that these folks were trying to sneak past our outpost using forbidden methods.",
  ui_story_5060_50600601_3_dialog_content = "While we were negotiating and trying to arrest them, we got ambushed by Eclipsites and failed to bring them in.",
  ui_story_5060_50600601_4_dialog_content = "All thanks to Deputy Captain Elma's intervention, we were saved; otherwise, we would have been buried under the yellow sands for sure.",
  ui_story_5060_50600601_5_dialog_content = "Don't mention it! You guys saved me from starving in the wilderness too, remember?",
  ui_story_5060_50600601_6_dialog_content = "Well, It sounds like we'll find a stronghold or transportation route for the smugglers somewhere in the Rediesel Desert.",
  ui_story_5060_50600601_7_dialog_content = "Coming to this Illumina Outpost was the right call, after all!",
  ui_story_5060_50600601_8_dialog_content = "But we still haven't heard anything about Fafnir.",
  ui_story_5060_50600601_9_dialog_content = "That's true. I had some people tap into Illumina's intelligence network for more information, but we didn't find anything.",
  ui_story_5060_50600601_10_dialog_content = "But there's no need to worry. Fafnir's the type to survive no matter where he finds himself.",
  ui_story_5060_50600601_11_dialog_content = "And who knows? Maybe we'll run into your last missing friend at our next delivery address?",
  ui_story_5060_50600601_12_dialog_content = "This world can be pretty small, after all.",
  ui_story_5060_50600601_13_dialog_content = "You're right.",
  ui_story_5060_50600601_14_dialog_content = "What food are we delivering this time, Tohru?",
  ui_story_5060_50600601_15_dialog_content = "This one isn't a food order, actually. The shop likes to thank its regular customers with some special sauces, so that's what we're delivering.",
  ui_story_5060_50600601_16_dialog_content = "And the address is in... The Rediesel Desert? Wow, what a coincidence. Will Fafnir show up somewhere out there too?",
  ui_story_5060_50600601_17_dialog_content = "Remember what those smugglers said? They risked getting hunted down by a dragon just to steal some sort of treasure from it.",
  ui_story_5060_50600601_18_dialog_content = "The dragon from the auction's collection?",
  ui_story_5060_50600601_19_dialog_content = "When I overheard the smugglers, I knew they were definitely not talking about Fafnir.",
  ui_story_5060_50600601_20_dialog_content = "No matter which world he's in or who his opponent is, Fafnir will resort to any means to acquire treasure.",
  ui_story_5060_50600601_21_dialog_content = "Is your friend really that scary?",
  ui_story_5060_50600601_22_dialog_content = "Don't worry, he's known to get along peaceably with other people! Just not that many of them!",
  ui_story_5060_50600601_23_option_content = "Still sounds a little scary...",
  ui_story_5060_50600601_24_option_content = "Sounds like an unapproachable dragon",
  ui_story_5060_50600601_25_dialog_content = "Relax, you're with us, remember? If worst comes to worst, we'll just gang up on him!",
  ui_story_5060_50600601_26_dialog_content = "Even though I'm still pretty scared, we have to keep going...",
  ui_story_5060_50600601_27_dialog_content = "It's time to bring this auction smuggling incident to an end!",
  ui_story_5060_50600601_28_dialog_content = "I promised the same to my boss. If there's anything I can do to help, I'll do my best to lend a hand!",
  ui_story_5060_50600601_29_dialog_content = "Lucoa can be really dependable when she's not slacking off.",
  ui_story_5060_50600601_30_dialog_content = "Do you know exactly where to find this address, PlayerName?",
  ui_story_5060_50600601_31_dialog_content = "I'm kind of familiar with it. It's one of the Rediesel Wrench's strongholds.",
  ui_story_5060_50600601_32_dialog_content = "Now that I think about it, I'm probably overdue for a trip out there.",
  ui_story_5060_50600601_33_dialog_content = "Even though they scavenge the desert, they also know how to engage in honest trade.",
  ui_story_5060_50600601_34_dialog_content = "But if we want to enter their territory safely, it's best if you let me greet them first.",
  ui_story_5060_50600601_35_dialog_content = "PlayerName is super reliable.",
  ui_story_5060_50600601_36_dialog_content = "Tohru, leave your motorcycle with these soldiers, so they can take it back to the outpost. Otherwise, there's a good chance those Rediesel Wrench guys will try to take it away.",
  ui_story_5060_50600601_37_dialog_content = "Even though they usually drive around in their own vehicles, it's better to be prepared.",
  ui_story_5060_50600601_38_dialog_content = "Don't worry, Miss Tohru. We'll take care of this motorcycle!",
  ui_story_5060_50600601_39_dialog_content = "Where'd those no-good smugglers crawl off to?!",
  ui_story_5060_50600601_40_dialog_content = "Looks like the smugglers have already crossed the Rediesel Wrench. They must not be afraid of anyone...",
  ui_story_5060_50600601_41_dialog_content = "Let me introduce everyone! This is Sinsa, the current leader of Rediesel Wrench.",
  ui_story_5060_50600601_42_dialog_content = "And over here are my newest friends!",
  ui_story_5060_50600601_43_dialog_content = "This guy looks really tough! Wanna see who's tougher, big guy?",
  ui_story_5060_50600601_44_dialog_content = "Sorry, but I've never hit a woman in my life, much less a maid.",
  ui_story_5060_50600601_45_dialog_content = "Hey, PlayerName! You said you knew something about those stinkin' smugglers, right? I won't rest until I clobber those idiots first!",
  ui_story_5060_50600601_46_dialog_content = "Don't tell me those guys stole something from you?",
  ui_story_5060_50600601_47_dialog_content = "Hell no! Those guys could've been ten times braver, and they still wouldn't have the guts to steal from us!",
  ui_story_5060_50600601_48_dialog_content = "Truth is, these smugglers used to be pretty quiet here in the Rediesel Desert.",
  ui_story_5060_50600601_49_dialog_content = "I don't know what got in their heads, but they've been causing all sorts of trouble lately.",
  ui_story_5060_50600601_50_dialog_content = "They almost looked delirious, running around and screaming about monsters and \"impending doom\" or whatever!",
  ui_story_5060_50600601_51_dialog_content = "They've already hugely impacted our daily operations!",
  ui_story_5060_50600601_52_dialog_content = "Because of them, we're hardly getting any Lumopolis caravans traveling through the desert!",
  ui_story_5060_50600601_53_dialog_content = "Oh... Uh...",
  ui_story_5060_50600601_54_dialog_content = "Do you actually have any information on them? If you do, just spit it out already!",
  ui_story_5060_50600601_55_dialog_content = "W-We were gonna ask you for more information about them.",
  ui_story_5060_50600601_56_dialog_content = "Like if they lost any treasure recently?",
  ui_story_5060_50600601_57_dialog_content = "Join the Rediesel Wrench, and I might be inclined to tell you.",
  ui_story_5060_50600601_58_dialog_content = "Not this again... Never mind, I'll just go ask Odi.",
  ui_story_5060_50600601_59_dialog_content = "She's the one keeping tabs on everything around here.",
  ui_story_5060_50600601_60_dialog_content = "You seem really popular, PlayerName.",
  ui_story_5060_50600601_61_dialog_content = "Oh right, I almost forgot.",
  ui_story_5060_50600601_62_dialog_content = "Allow me to introduce myself! My name is Tohru, a delivery maid from Mr. Liu's restaurant!",
  ui_story_5060_50600601_63_dialog_content = "Is anyone here one of Mr. Liu's regular customers? If so, I have some sauce to deliver on his behalf!",
  ui_story_5060_50600601_64_dialog_content = "Whoa, never thought I'd get my hands on this good stuff?! Hand it over, quick!",
  ui_story_5060_50600601_65_dialog_content = "I've been the one to go out and get it several times; why should I let you have it?!",
  ui_story_5060_50600601_66_dialog_content = "It's my vouchers that all of you have been using!",
  ui_story_5060_50600601_67_dialog_content = "Quit your squabbling or I'll confiscate everything!",
  ui_story_5060_50600601_68_dialog_content = "Let's go back to the Rediesel Wrench's stronghold first. Come on, PlayerName; you and your friends can ride with me.",
  ui_story_5060_50600601_69_dialog_content = "The rest of you can follow behind me in the other car!",
  ui_story_5060_50600601_70_dialog_content = "Sure thing.",
  ui_story_5060_50600601_71_dialog_content = "Alright, friends! Time to experience the speed and excitement of the Rediesel Wrench!",
  ui_story_5060_50600601_72_dialog_content = "Now hang on tight!",
  ui_story_5060_50600601_73_dialog_content = "<size=45>Liftoff!</size>",
  ui_story_5060_50600601_74_dialog_content = "Woohoo! What an awesome way to drive!",
  ui_story_5060_50600601_75_dialog_content = "Are you doing okay, Kanna?",
  ui_story_5060_50600601_76_dialog_content = "I'm fine. This is exciting.",
  ui_story_5060_50600601_77_dialog_content = "That's good, but it looks like something's wrong with PlayerName!",
  ui_story_5060_50600601_78_dialog_content = "You're not feeling carsick, are you?",
  ui_story_5060_50600601_79_dialog_content = "A Colossus pilot could never get carsick!",
  ui_story_5060_50600601_80_dialog_content = "It's not good to push yourself, you know?",
  ui_story_5060_50600601_81_dialog_content = "Just lean on me and everything will be okay!",
  ui_story_5060_50600601_82_dialog_content = "N-No thanks.",
  ui_story_5060_50600601_83_dialog_content = "Did you feel the speed and excitement of the Rediesel Wrench?",
  ui_story_5060_50600601_84_dialog_content = "This next part is gonna be a little bumpy, so try not to get thrown off!",
  ui_story_5060_50600601_85_dialog_content = "Before meeting you, I couldn't stop wondering what the Rediesel Wrench was like.",
  ui_story_5060_50600601_86_dialog_content = "After all, PlayerName said you were the kind to forcibly take my motorcycle!",
  ui_story_5060_50600601_87_dialog_content = "I thought you guys would be a bunch of thugs with bad attitudes...",
  ui_story_5060_50600601_88_dialog_content = "But now I see that I was wrong to think that.",
  ui_story_5060_50600601_89_dialog_content = "Hahaha, don't worry about it! We all make mistakes every now and then!",
  ui_story_5060_50600601_90_dialog_content = "But as long as we speak openly and trust one another, we'll always be friends running through this crazy desert!",
  ui_story_5060_50600601_91_dialog_content = "The Rediesel Wrench is all about freedom!",
  ui_story_5060_50600601_92_dialog_content = "A little too much freedom, if you ask me—",
  ui_story_5060_50600801_1_dialog_content = "I feel dizzy.",
  ui_story_5060_50600801_2_dialog_content = "Really dizzy.",
  ui_story_5060_50600801_3_dialog_content = "Come here, Kanna. Let me hold you.",
  ui_story_5060_50600801_4_dialog_content = "I didn't think you would be the one to get carsick in the end.",
  ui_story_5060_50600801_5_dialog_content = "There's no helping it; after all, she's still so young and I'm sure this is her first time on such a bumpy ride.",
  ui_story_5060_50600801_6_dialog_content = "Anyway, I'm starting to get a little hungry. When can we eat?",
  ui_story_5060_50600801_7_dialog_content = "You were keeping quiet this whole time because you didn't want to get hungry from talking, huh?",
  ui_story_5060_50600801_8_dialog_content = "N-No! I've been on the lookout for Eclipsites all the time!",
  ui_story_5060_50600801_9_dialog_content = "We took down a bunch of them earlier. You could've eaten as many as you wanted.",
  ui_story_5060_50600801_10_dialog_content = "How could I eat something like that?!",
  ui_story_5060_50600801_11_dialog_content = "Well, what about the sweets those Illumina soldiers gave you?",
  ui_story_5060_50600801_12_dialog_content = "Those are a token of our camaraderie!",
  ui_story_5060_50600801_13_dialog_content = "I'm planning on bringing those back home with us! It won't mean anything if I eat them now!",
  ui_story_5060_50600801_14_dialog_content = "Ah, forget it... Here. Mr. Liu gave me a few extra, but I can't eat them all.",
  ui_story_5060_50600801_15_dialog_content = "You really are a good friend, Tohru!",
  ui_story_5060_50600801_16_dialog_content = "G-Get off of me!",
  ui_story_5060_50600801_17_dialog_content = "For having survived such an intense battle just now, you two sure are full of energy.",
  ui_story_5060_50600801_18_dialog_content = "Are you talking about those Eclipsites in the desert? Dealing with those pests is nothing for someone like me!",
  ui_story_5060_50600801_19_dialog_content = "Still, when we finally got to the desert, I thought there would be a lot less of them here.",
  ui_story_5060_50600801_20_dialog_content = "Then why are there still so many Eclipsites?",
  ui_story_5060_50600801_21_dialog_content = "If there's one thing this world doesn't lack, it's Eclipsites. Wherever you find Aurorians, those monsters will never be too far off—",
  ui_story_5060_50600801_22_dialog_content = "But even places without Aurorians are swarming with Eclipsites!",
  ui_story_5060_50600801_23_dialog_content = "Well, thanks to Odi's vast surveillance system, we can track most of their movements and prepare accordingly.",
  ui_story_5060_50600801_24_dialog_content = "It also helps you defend your strongholds from Lumopolis' army, right?",
  ui_story_5060_50600801_25_dialog_content = "Hahaha! Blunt as usual, PlayerName! That's what I like about you!",
  ui_story_5060_50600801_26_dialog_content = "Alright, Odi should be inside. Ask her whatever you want.",
  ui_story_5060_50600801_27_dialog_content = "Odi—",
  ui_story_5060_50600801_28_dialog_content = "Huh? Who's the one next to her?",
  ui_story_5060_50600801_29_dialog_content = "You're pretty good, <color=#FFB400>Fafnir</color>, but if you want to beat me...",
  ui_story_5060_50600801_30_dialog_content = "You still have a long way to go!",
  ui_story_5060_50600801_31_dialog_content = "Take this—",
  ui_story_5060_50600801_32_dialog_content = "<size=45>Star Piercer!</size>",
  ui_story_5060_50600801_33_dialog_content = "Wait, don't use that move!",
  ui_story_5060_50600801_34_dialog_content = "...",
  ui_story_5060_50600801_35_dialog_content = "Fafnir looked so injured; he didn't even greet us when we came in.",
  ui_story_5060_50600801_36_dialog_content = "Hey Fafnir, you still alive?",
  ui_story_5060_50600801_37_dialog_content = "I think his soul already left his body. He must have lost really badly.",
  ui_story_5060_50600801_38_dialog_content = "I didn't lose. I'm just not in the mood, is all.",
  ui_story_5060_50600801_39_dialog_content = "Long time no see, PlayerName! Are you bringing these new friends to play games today?",
  ui_story_5060_50600801_40_dialog_content = "Yes. And they also happen to be Fafnir's friends as well.",
  ui_story_5060_50600801_41_dialog_content = "(So this is Fafnir... He has such a ferocious look in his eyes.)",
  ui_story_5060_50600801_42_dialog_content = "(At a time like this, a friendly greeting seems extremely important for closing the gap between us.)",
  ui_story_5060_50600801_43_dialog_content = "Hey there, Faffy! My name's PlayerName, and I'm one of Tohru's...",
  ui_story_5060_50600801_44_dialog_content = "Don't address me with such an informal name.",
  ui_story_5060_50600801_45_dialog_content = "Er... A-Anyway, we came here to ask Odi for a little information.",
  ui_story_5060_50600801_46_dialog_content = "As long as you don't ask me to join the Rediesel Wrench, we'll go along with any conditions you have for us.",
  ui_story_5060_50600801_47_dialog_content = "\"Conditions\"? I don't care about that! I just stomped this guy three hundred times in a row, so I'm in a great mood!",
  ui_story_5060_50600801_48_dialog_content = "Correction: it was two-hundred and ninety-nine times.",
  ui_story_5060_50600801_49_dialog_content = "Eh, close enough. Anyway, I'll help you out for free this time.",
  ui_story_5060_50600801_50_dialog_content = "(Thanks, <size=45>Faffy!</size>)",
  ui_story_5060_50600801_51_dialog_content = "I need your help finding some footage related to a group of smugglers. I can show you roughly which way they were moving...",
  ui_story_5060_50600801_52_dialog_content = "So you were with the Rediesel Wrench all this time, Fafnir?",
  ui_story_5060_50600801_53_dialog_content = "You're a treasure-hoarding dragon, but judging from their nature... It's clear that the Rediesel Wrench is a group of treasure hunters.",
  ui_story_5060_50600801_54_dialog_content = "I'm honestly surprised you stuck around for so long...",
  ui_story_5060_50600801_55_dialog_content = "Did they bribe you with a lifetime supply of sweets or something?!",
  ui_story_5060_50600801_56_dialog_content = "Fafnir isn't an insatiable glutton like you, Elma.",
  ui_story_5060_50600801_57_dialog_content = "So long as my opponent earns my approval, I have no problem interacting with them as equals.",
  ui_story_5060_50600801_58_dialog_content = "It has absolutely nothing to do with profession, status, or value in society.",
  ui_story_5060_50600801_59_dialog_content = "Where are you going, Fafnir?",
  ui_story_5060_50600801_60_dialog_content = "I'm going out for some air.",
  ui_story_5060_50600801_61_dialog_content = "How could I have lost so miserably? Where did I go wrong?",
  ui_story_5060_50600801_62_dialog_content = "Could it be a question of willpower?",
  ui_story_5060_50600802_1_dialog_content = "What do you want? I'm still thinking of a way to defeat Odi.",
  ui_story_5060_50600802_2_dialog_content = "Don't worry, you'll have all the time in the world to think about it later.",
  ui_story_5060_50600802_3_dialog_content = "Just go back inside for now. Odi has something to tell you.",
  ui_story_5060_50600802_4_dialog_content = "Hmph... I'm sure she just wants to gloat about her victories.",
  ui_story_5060_50600802_5_dialog_content = "I hate to admit it, but right now... She's better than me.",
  ui_story_5060_50600802_6_dialog_content = "You'd better watch your tone.",
  ui_story_5060_50600802_7_dialog_content = "If you go too far, I might just curse you into dust.",
  ui_story_5060_50600802_8_dialog_content = "What the heck's he going on about?",
  ui_story_5060_50600802_9_dialog_content = "Don't mind him, he just likes to sound edgy!",
  ui_story_5060_50600802_10_dialog_content = "You ran off so quickly just now that I didn't have time to give you my gift.",
  ui_story_5060_50600802_11_dialog_content = "Your gift. For me?",
  ui_story_5060_50600802_12_dialog_content = "Here, it's the latest version of this game machine.",
  ui_story_5060_50600802_13_dialog_content = "Cheer up, Fafnir! My genius hands built this from scratch, which makes it just as priceless as any treasure!",
  ui_story_5060_50600802_14_dialog_content = "So you're not going to humiliate me?",
  ui_story_5060_50600802_15_dialog_content = "Humiliate you? There's no need for that anymore. Besides, I acknowledged you as a worthy opponent a long time ago.",
  ui_story_5060_50600802_16_dialog_content = "Even a gaming addict like Gronru wasn't able to give me the trial data I needed with this game machine.",
  ui_story_5060_50600802_17_dialog_content = "You're the first and only person to go three hundred rounds against me, and I couldn't be more grateful for that!",
  ui_story_5060_50600802_18_dialog_content = "Alright, now it's time to handle PlayerName's request.",
  ui_story_5060_50600802_19_dialog_content = "Can I ask how you plan to do that?",
  ui_story_5060_50600802_20_dialog_content = "It's simple! First, I'll have the surveillance system perform an automatic search, and then I'll compare the images it pulls up.",
  ui_story_5060_50600802_21_dialog_content = "Fine... I don't get how that works at all. Forget I asked.",
  ui_story_5060_50600802_22_dialog_content = "And how much time will it take?",
  ui_story_5060_50600802_23_dialog_content = "Twenty minutes or so.",
  ui_story_5060_50600802_24_dialog_content = "Why have you been pacing all this time, Fafnir? Let me guess, you're planning on giving Odi that book in your hands as a gift?",
  ui_story_5060_50600802_25_dialog_content = "That's none of your business.",
  ui_story_5060_50600802_26_dialog_content = "Let's see what kind of book this is.",
  ui_story_5060_50600802_27_dialog_content = "Oh man, not your stupid book of curses again!",
  ui_story_5060_50600802_28_dialog_content = "Miss Odi has an insatiable thirst for knowledge! If she laid eyes on this book, who knows what would happen?!",
  ui_story_5060_50600802_29_dialog_content = "Why don't you give her a different gift instead?",
  ui_story_5060_50600802_30_dialog_content = "Tch.",
  ui_story_5060_50600802_31_dialog_content = "Which reminds me, we should also give our new friends from the Rediesel Wrench some commemorative gifts!",
  ui_story_5060_50600802_32_dialog_content = "Uh, Miss Tohru?",
  ui_story_5060_50600802_33_dialog_content = "Why do you... Keep staring at me like that? Is there something stuck to my tail?",
  ui_story_5060_50600802_34_dialog_content = "Not at all! I was just thinking that with a big, wonderful tail like yours... You would look really beautiful in a maid costume, Maggie!",
  ui_story_5060_50600802_35_dialog_content = "Have you ever thought of entering the world of maids?",
  ui_story_5060_50600802_36_dialog_content = "I bet Kobayashi would be super thrilled if she saw you in a maid costume too!",
  ui_story_5060_50600802_37_dialog_content = "Here, try it on for yourself!",
  ui_story_5060_50600802_38_dialog_content = "Sob, sob, sob—",
  ui_story_5060_50600802_39_dialog_content = "Barbara, Regina, save meeeee—",
  ui_story_5060_50600802_40_dialog_content = "You two have such unique singing voices! I just wish Shouta could be here to listen too.",
  ui_story_5060_50600802_41_dialog_content = "Hahaha! Well, music is meant to be shared and enjoyed by everyone!",
  ui_story_5060_50600802_42_dialog_content = "Sob, sob, sob—",
  ui_story_5060_50600802_43_dialog_content = "B-Brock, please help me...",
  ui_story_5060_50600802_44_dialog_content = "Hey Kanna, did you know?",
  ui_story_5060_50600802_45_dialog_content = "I'm actually the real boss of the Rediesel Wrench!",
  ui_story_5060_50600802_46_dialog_content = "But I've always been more of a low-key type of person, see? That's why Sinsa's the boss on paper.",
  ui_story_5060_50600802_47_dialog_content = "Whoa—",
  ui_story_5060_50600802_48_dialog_content = "A secret boss. That's so cool.",
  ui_story_5060_50600802_49_dialog_content = "He's completely useless too...",
  ui_story_5060_50600802_50_dialog_content = "Th-Th-Then I'll just ask Jomu! Jomu will save me for sure!",
  ui_story_5060_50600802_51_dialog_content = "You've had your eyes on my food selection for quite a while, my pretty, young guest! You must suffer from some serious buyer's indecision, yes?",
  ui_story_5060_50600802_52_dialog_content = "Then why don't I introduce you to my latest specialty product: the Mystery Dessert Box!",
  ui_story_5060_50600802_53_dialog_content = "Each box contains a different type of dessert.",
  ui_story_5060_50600802_54_dialog_content = "In other words, each box contains a future that belongs to you and no one else!",
  ui_story_5060_50600802_55_dialog_content = "What's more, I'm running a very special promotion right now, and a single Mystery Box will only cost you 2,000 Nightium! It's a steal at that price!",
  ui_story_5060_50600802_56_dialog_content = "I'll take all of them!!!",
  ui_story_5060_50600802_57_dialog_content = "Don't be shy! I can even use scales to make a custom-tailored maid costume just for you, Maggie!",
  ui_story_5060_50600802_58_dialog_content = "All I ask is that you take a picture with me afterward!",
  ui_story_5060_50600802_59_dialog_content = "N-N-N-No, please—",
  ui_story_5060_50600802_60_dialog_content = "Chief! I'm back from my hunt, and I scored another huge haul today!",
  ui_story_5060_50600802_61_dialog_content = "I also dug up a bunch of sand spiders. Take a look.",
  ui_story_5060_50600802_62_dialog_content = "What's with all the unfamiliar faces, chief? Are these guys guests?",
  ui_story_5060_50600802_63_dialog_content = "I'll introduce you in a minute. Just go drop the food off in the kitchen first.",
  ui_story_5060_50600802_64_dialog_content = "...",
  ui_story_5060_50600802_65_dialog_content = "Ah! That little girl just ate all the sand spiders I worked so hard to dig up!!!",
  ui_story_5060_50600802_66_dialog_content = "Hmm. Those were yummy.",
  ui_story_5060_50600802_67_dialog_content = "Kanna! No eating other people's stuff without getting their permission first!",
  ui_story_5060_50600802_68_dialog_content = "Oh. Sorry.",
  ui_story_5060_50600802_69_dialog_content = "You're pretty brave, little girl! I can't believe you ate all of those sand spiders raw!",
  ui_story_5060_50600802_70_dialog_content = "Aside from our boss and Brock, you're definitely the first person I've seen do something like that!",
  ui_story_5060_50600802_71_dialog_content = "Yummy.",
  ui_story_5060_50600802_72_dialog_content = "Honestly... How many times has Kobayashi told you to stop putting everything in your mouth?",
  ui_story_5060_50600802_73_dialog_content = "Oh...",
  ui_story_5060_50600802_74_dialog_content = "I wonder how Kobayashi is doing back in her world. Is she worried about me right now?",
  ui_story_5060_50600802_75_dialog_content = "Here, Miss Tohru. Have some water.",
  ui_story_5060_50600802_76_dialog_content = "...",
  ui_story_5060_50600802_77_dialog_content = "What's the matter, don't like water from the desert?",
  ui_story_5060_50600802_78_dialog_content = "That's not it.",
  ui_story_5060_50600802_79_dialog_content = "This warm and cozy scene just reminded me of Kobayashi.",
  ui_story_5060_50600802_80_dialog_content = "I haven't gone back after all this time. She's probably worried sick about me...",
  ui_story_5060_50600802_81_dialog_content = "I managed to find everyone, but we still don't have a way to return to our world... Sigh.",
  ui_story_5060_50600802_82_dialog_content = "Right, PlayerName told me all about your guys' situation.",
  ui_story_5060_50600802_83_dialog_content = "So you're really from another world, huh? If anyone else told me that, I wouldn't believe 'em for a second.",
  ui_story_5060_50600802_84_dialog_content = "PlayerName says you guys just need to find a place where the mana isn't so unstable, and you can go home. Is that right?",
  ui_story_5060_50600802_85_dialog_content = "Actually, the mana here in the Rediesel Desert should be stable enough to use.",
  ui_story_5060_50600802_86_dialog_content = "But I tried a while ago, and I still can't get the portal to activate properly. Maybe I still need even more power.",
  ui_story_5060_50600802_87_dialog_content = "And if I can't get it to work, then the others definitely...",
  ui_story_5060_50600802_88_dialog_content = "I'm really sorry.",
  ui_story_5060_50600802_89_dialog_content = "You all have your own problems, yet you're still helping me crack this smuggling case.",
  ui_story_5060_50600802_90_dialog_content = "It's fine! We want to help, you know.",
  ui_story_5060_50600802_91_dialog_content = "After all, we're friends now. Aren't we?",
  ui_story_5060_50600802_92_dialog_content = "That's right! You're also a friend of the Rediesel Wrench, since you and PlayerName helped us wipe out all those Eclipsites along the way!",
  ui_story_5060_50600802_93_dialog_content = "We'll help you guys figure something out!",
  ui_story_5060_50600802_94_dialog_content = "Yes... I'm certain we'll find a way back too.",
  ui_story_5060_50600802_95_dialog_content = "And when we do, I'll be sure to tell Kobayashi all about our adventure! So when we finally come back to visit this world again...",
  ui_story_5060_50600802_96_dialog_content = "When we come back to visit again...",
  ui_story_5060_50600802_97_dialog_content = "Tohru...",
  ui_story_5060_50600802_98_dialog_content = "It's purely a coincidence that we came to your world this time.",
  ui_story_5060_50600802_99_dialog_content = "But next time... if we're lucky enough to come back again...",
  ui_story_5060_50600802_100_dialog_content = "Nobody knows what'll happen in the future, so there's no use thinking about it too much right now.",
  ui_story_5060_50600802_101_dialog_content = "That's right, Tohru! Let's just eat first!",
  ui_story_5060_50600802_102_dialog_content = "I really envy you sometimes. All you need to do is eat your fill every day to be happy.",
  ui_story_5060_50600802_103_dialog_content = "But this time, you're right...",
  ui_story_5060_50600802_104_dialog_content = "We should eat first.",
  ui_story_5060_50600802_105_dialog_content = "I'll go prepare the ingredients!",
  ui_story_5060_50600802_106_dialog_content = "Here you go! A Rediesel-style spicy insect platter!",
  ui_story_5060_50600802_107_dialog_content = "Nice! This food's perfect for Rediesel Wrench! I'm making this a regular dish for us!",
  ui_story_5060_50600802_108_dialog_content = "Take notes, Maggie! You should try to become an awesome maid, just like Tohru!",
  ui_story_5060_50600802_109_dialog_content = "Huh?",
  ui_story_5060_50600802_110_dialog_content = "<size=45>What?!</size>",
  ui_story_5060_50600802_111_dialog_content = "Is there still any left? I want some too!",
  ui_story_5060_50600802_112_dialog_content = "I could definitely make a fortune by selling this.",
  ui_story_5060_50600802_113_dialog_content = "Do you have any spare time, Miss Tohru? Would you mind sharing the recipe with me?",
  ui_story_5060_50600802_114_dialog_content = "I'll give you 10,000 Nightium for it.",
  ui_story_5060_50600802_115_dialog_content = "I'm full. Now I'm sleepy.",
  ui_story_5060_50600802_116_dialog_content = "Here Kanna, you can rest on my legs.",
  ui_story_5060_50600802_117_dialog_content = "I should eat some to regain some energy too. The search should be done any second now.",
  ui_story_5060_50600802_118_dialog_content = "You know, the food here is really unique. Maybe this stuff will be useful for treating Kobayashi's back pain?",
  ui_story_5060_50600802_119_dialog_content = "I'm willing to bet she won't touch any of it.",
  ui_story_5060_50600802_120_dialog_content = "You should just take a few more photos and bring them back to her.",
  ui_story_5060_50600802_121_dialog_content = "You have a point. So you can say some sensible things every now and then, huh?",
  ui_story_5060_50600802_122_dialog_content = "Hey—",
  ui_story_5060_50600901_1_dialog_content = "As expected, nothing gets past a genius hacker like me!",
  ui_story_5060_50600901_2_dialog_content = "I found some footage of those smugglers falling under attack.",
  ui_story_5060_50600901_3_dialog_content = "And it looks like they dropped whatever they were transporting there.",
  ui_story_5060_50600901_4_dialog_content = "They were attacked?",
  ui_story_5060_50600901_5_dialog_content = "They were lying all along. Jerks.",
  ui_story_5060_50600901_6_dialog_content = "These wicked violators of order should be crushed by the iron fist of justice!",
  ui_story_5060_50600901_7_dialog_content = "So the lost treasure has nothing to do with the Cloudrover Guild? Looks like Lady Sheol can take it easy now.",
  ui_story_5060_50600901_8_dialog_content = "Either way, let's head out there and take a look first.",
  ui_story_5060_50600901_9_dialog_content = "...",
  ui_story_5060_50600901_10_dialog_content = "We must have lost that guy by now, right...",
  ui_story_5060_50600901_11_dialog_content = "Wh-what in the world is that?! I've never seen any creature like that before!",
  ui_story_5060_50600901_12_dialog_content = "What's with the fuss, huh?!",
  ui_story_5060_50600901_13_dialog_content = "We're seasoned smugglers who have seen the world.",
  ui_story_5060_50600901_14_dialog_content = "It's probably just some desert-dwelling dragon.",
  ui_story_5060_50600901_15_dialog_content = "Hahaha, we've surely lost him by now!",
  ui_story_5060_50600901_16_dialog_content = "Chief, please quit laughing.",
  ui_story_5060_50600901_17_dialog_content = "Remember the last time you laughed out loud? We got attacked by Eclipsites right away...",
  ui_story_5060_50600901_18_dialog_content = "Really? You must remember it wrong! Hahaha!",
  ui_story_5060_50600901_19_dialog_content = "Noooooo! This is bad—!",
  ui_story_5060_50600901_20_dialog_content = "B-behind us! That guy is right on our tails!",
  ui_story_5060_50600901_21_dialog_content = "...",
  ui_story_5060_50600901_22_dialog_content = "Chief, what's the plan?",
  ui_story_5060_50600901_23_dialog_content = "How about ditching the car and making a run for it?",
  ui_story_5060_50600901_24_dialog_content = "You idiot!",
  ui_story_5060_50600901_25_dialog_content = "Do you want to be a laughingstock in front of the boss and other gangs forever?",
  ui_story_5060_50600901_26_dialog_content = "We went through hell and high water to nab that treasure!",
  ui_story_5060_50600901_27_dialog_content = "Isn't it just an <color=#FFB400>egg</color>...",
  ui_story_5060_50600901_28_dialog_content = "Umbraton is full of treasures. I doubt this one is such a big deal...",
  ui_story_5060_50600901_29_dialog_content = "You mindless jerk! That's a <color=#FFB400>dragon egg</color> you're talkin' about!",
  ui_story_5060_50600901_30_dialog_content = "Chief, that guy's getting closer!",
  ui_story_5060_50600901_31_dialog_content = "Step on it! Full throttle! Let's roll!",
  ui_story_5060_50600901_32_dialog_content = "Once we get this egg out of the desert and deliver it to the hands of the contact, our job is done!",
  ui_story_5060_50600901_33_dialog_content = "Chief, watch out!",
  ui_story_5060_50600901_34_dialog_content = "Mortals.",
  ui_story_5060_50600901_35_dialog_content = "How utterly foolish.",
  ui_story_5060_50600901_36_dialog_content = "We went through so much trouble to grab that dragon's egg! And now, he...",
  ui_story_5060_50600901_37_dialog_content = "Go back and tell your leader:",
  ui_story_5060_50600901_38_dialog_content = "Never steal from a dragon ever again.",
  ui_story_5060_50600901_39_dialog_content = "This is your only warning.",
  ui_story_5060_50600901_40_dialog_content = "Next time, not even your bones will remain in this world.",
  ui_story_5060_50600901_41_dialog_content = "No way...",
  ui_story_5060_50600901_42_dialog_content = "But how...?",
  ui_story_5060_50600901_43_dialog_content = "Oh my, what an unexpected twist!",
  ui_story_5060_50600901_44_dialog_content = "Defeating this final boss won't be easy.",
  ui_story_5060_50600901_45_dialog_content = "Tohru, are you...",
  ui_story_5060_50600901_46_dialog_content = "Are you all right?",
  ui_story_5060_50600901_47_dialog_content = "Is that person from your world as well?",
  ui_story_5060_50600901_48_dialog_content = "Yes.",
  ui_story_5060_50600901_49_dialog_content = "That's Tohru's father, as well as the leader of the Chaos Faction: Damocles, the<color=#FFB400>Emperor of Demise</color>.",
  ui_story_5060_50601001_1_dialog_content = "I see. Everything makes a lot more sense now.",
  ui_story_5060_50601001_2_dialog_content = "Tohru's father discovered the smugglers trying to steal that dragon egg, and it ultimately ended up in his possession.",
  ui_story_5060_50601001_3_dialog_content = "So to avoid getting punished by their leader, the smugglers tried to shift the blame onto other people.",
  ui_story_5060_50601001_4_dialog_content = "Father...",
  ui_story_5060_50601001_5_dialog_content = "So he's in this world as well...",
  ui_story_5060_50601001_6_dialog_content = "Wait a minute, he might be able to—",
  ui_story_5060_50601001_7_dialog_content = "Hey! You're not about to do something stupid again, are you?!",
  ui_story_5060_50601001_8_dialog_content = "But I didn't say anything!",
  ui_story_5060_50601001_9_dialog_content = "We've known each other long enough.",
  ui_story_5060_50601001_10_dialog_content = "You were clearly going to ask the Emperor of Demise if you could come back to this world again!",
  ui_story_5060_50601001_11_dialog_content = "After all, if anyone could do that, it's him.",
  ui_story_5060_50601001_12_dialog_content = "...",
  ui_story_5060_50601001_13_dialog_content = "You're right.",
  ui_story_5060_50601001_14_dialog_content = "He definitely came here to get me, but if I go with him now, he'll never let me return to this world.",
  ui_story_5060_50601001_15_dialog_content = "Don't you and the others want to come back too, Elma?!",
  ui_story_5060_50601001_16_dialog_content = "I understand. I know we can't stay here too long, since the presence of dragons will disrupt the natural order of this world...",
  ui_story_5060_50601001_17_dialog_content = "But we can still set aside plenty of time to try all the wonderful food it has to offer!",
  ui_story_5060_50601001_18_dialog_content = "This world is lots of fun. It would be a shame if we could never come back!",
  ui_story_5060_50601001_19_dialog_content = "I want to see that girl again.",
  ui_story_5060_50601001_20_dialog_content = "And I still haven't defeated that woman.",
  ui_story_5060_50601001_21_dialog_content = "Leaving like this would be no different from running away. I refuse to do something so shameful.",
  ui_story_5060_50601001_22_dialog_content = "Is your father really that unwilling to listen, Tohru?",
  ui_story_5060_50601001_23_dialog_content = "For dragons, power is everything.",
  ui_story_5060_50601001_24_dialog_content = "Right now, I'm not strong enough to defeat my father...",
  ui_story_5060_50601001_25_dialog_content = "Which means I have no way of convincing him to accept my wishes...",
  ui_story_5060_50601001_26_dialog_content = "But even so, that doesn't mean I shouldn't try! Even if there's only a tiny sliver of hope, I refuse to give up so easily!",
  ui_story_5060_50601001_27_dialog_content = "<color=#e8d9bb>Crimson Blaze Canyon</color>",
  ui_story_5060_50601001_28_dialog_content = "This should be the place.",
  ui_story_5060_50601001_29_dialog_content = "Look, the dragon egg that the Emperor of Demise recovered is in that cave over there.",
  ui_story_5060_50601001_30_dialog_content = "You guys haven't said a word this whole time.",
  ui_story_5060_50601001_31_dialog_content = "Could it be...",
  ui_story_5060_50601001_32_dialog_content = "He's here too.",
  ui_story_5060_50601001_33_dialog_content = "My, what a terrifying presence!",
  ui_story_5060_50601001_34_dialog_content = "I'm pleased that you decided to show yourself, Tohru.",
  ui_story_5060_50601001_35_dialog_content = "Father.",
  ui_story_5060_50601001_36_dialog_content = "Come. We're leaving.",
  ui_story_5060_50601001_37_dialog_content = "The portal can be used at any time.",
  ui_story_5060_50601001_38_dialog_content = "I knew it...",
  ui_story_5060_50601001_39_dialog_content = "Even with the low mana levels of this world, you have no problem activating the portal.",
  ui_story_5060_50601001_40_dialog_content = "...",
  ui_story_5060_50601001_41_dialog_content = "Father! Can I speak to you about something?!",
  ui_story_5060_50601001_42_dialog_content = "Very well, so long as it isn't pointless.",
  ui_story_5060_50601001_43_dialog_content = "I know that you came here because you noticed something wrong with my own portal.",
  ui_story_5060_50601001_44_dialog_content = "And I want to go back to Kobayashi's world with you too.",
  ui_story_5060_50601001_45_dialog_content = "It's just...",
  ui_story_5060_50601001_46_dialog_content = "Just once in a while... Would it be alright if I came back to visit this world?",
  ui_story_5060_50601001_47_dialog_content = "No.",
  ui_story_5060_50601001_48_dialog_content = "But you're willing to let me live in Kobayashi's world!",
  ui_story_5060_50601001_49_dialog_content = "I don't recall agreeing to that.",
  ui_story_5060_50601001_50_dialog_content = "Furthermore, the inhabitants of this world are very similar to the humans in our world.",
  ui_story_5060_50601001_51_dialog_content = "Thievery, deception, prejudice, and infighting are all too common here.",
  ui_story_5060_50601001_52_dialog_content = "A number of these people also possess extraordinary abilities, which may have a profound influence on us as dragons.",
  ui_story_5060_50601001_53_dialog_content = "Staying in this world will only result in one of the two things for you:",
  ui_story_5060_50601001_54_dialog_content = "One, your presence will continue to tear away at the principles governing this world.",
  ui_story_5060_50601001_55_dialog_content = "Or two, you will be corrupted by the evils of this world and meet your demise.",
  ui_story_5060_50601001_56_dialog_content = "...",
  ui_story_5060_50601001_57_dialog_content = "Sorry, but could I just say a few words?",
  ui_story_5060_50601001_58_dialog_content = "My name is PlayerName, and I've been traveling with Tohru for most of her time here.",
  ui_story_5060_50601001_59_dialog_content = "It's a pleasure to meet you, Emperor of Demise! I'm also really grateful to you for retrieving that stolen dragon egg.",
  ui_story_5060_50601001_60_dialog_content = "I had no intention of breaking the rules of this world.",
  ui_story_5060_50601001_61_dialog_content = "But those thieves knew not fear nor contentment.",
  ui_story_5060_50601001_62_dialog_content = "They even thought they could use their puny bodies and primitive tools to make me into their next meal.",
  ui_story_5060_50601001_63_dialog_content = "All I did was teach them the true meaning of terror.",
  ui_story_5060_50601001_64_dialog_content = "Still, I believe good and evil exist within every world and all species.",
  ui_story_5060_50601001_65_dialog_content = "You just happened to run into the bad eggs of our world first.",
  ui_story_5060_50601001_66_dialog_content = "Are you trying to lecture me, child?",
  ui_story_5060_50601001_67_dialog_content = "I just think you need to see things as a whole first, instead of judging everything based on a few individual examples.",
  ui_story_5060_50601001_68_dialog_content = "Most of the people who have met Tohru and the others would never discriminate against them because they're from a different world.",
  ui_story_5060_50601001_69_dialog_content = "On the contrary, all of them chose to lend her their strength!",
  ui_story_5060_50601001_70_dialog_content = "I'll admit, the evils of war and prejudice definitely exist in our world.",
  ui_story_5060_50601001_71_dialog_content = "But there's also lots of good in it too!",
  ui_story_5060_50601001_72_dialog_content = "We may be different species living in different worlds, but the bonds we've built with Tohru and her friends will never be broken!",
  ui_story_5060_50601001_73_dialog_content = "...",
  ui_story_5060_50601001_74_dialog_content = "PlayerName!",
  ui_story_5060_50601001_75_dialog_content = "That was close! I would've gotten burnt to a crisp if I hadn't dodged in time!",
  ui_story_5060_50601001_76_dialog_content = "That's only because I missed on purpose.",
  ui_story_5060_50601001_77_dialog_content = "But if you continue spouting more confusing nonsense, I won't spare you so easily next time.",
  ui_story_5060_50601001_78_dialog_content = "It looks like you really don't trust me.",
  ui_story_5060_50601001_79_dialog_content = "Naturally not.",
  ui_story_5060_50601001_80_dialog_content = "The only things I trust are my own judgment and power.",
  ui_story_5060_50601001_81_dialog_content = "If you insist on letting Tohru stay in this filthy world of yours, then you'll have to join together and defeat me first.",
  ui_story_5060_50601001_82_dialog_content = "Show me the strength of your resolve.",
  ui_story_5060_50601001_83_dialog_content = "You don't have to do this if you don't want to, PlayerName...",
  ui_story_5060_50601001_84_dialog_content = "Bring it on then, Emperor of Demise! I'll show you just how strong our bond is with Tohru and her friends!",
  ui_story_5060_50601001_85_dialog_content = "This world isn't nearly as awful as you think!",
  ui_story_5060_50601002_1_dialog_content = "Not bad. Tohru never had this kind of power before.",
  ui_story_5060_50601002_2_dialog_content = "However—",
  ui_story_5060_50601002_3_dialog_content = "It's still not enough!",
  ui_story_5060_50601002_4_dialog_content = "So he was still hiding his true power, huh?",
  ui_story_5060_50601002_5_dialog_content = "We'll be in serious danger if the Emperor of Demise fights us at full strength, you know!",
  ui_story_5060_50601002_6_dialog_content = "Then you'll just have to fight back using your full strength too, Lucoa!",
  ui_story_5060_50601002_7_dialog_content = "But I'm already trying so hard!",
  ui_story_5060_50601002_8_dialog_content = "You're not fooling anyone!",
  ui_story_5060_50601002_9_dialog_content = "What should we do, Tohru?",
  ui_story_5060_50601002_10_dialog_content = "Even with PlayerName's psychic abilities, we still can't defeat the Emperor of Demise.",
  ui_story_5060_50601002_11_dialog_content = "And if we don't defeat him now, he'll never accept our request.",
  ui_story_5060_50601002_12_dialog_content = "I want to go back and be with Kobayashi, but I can't just abandon the bonds we made with our friends here!",
  ui_story_5060_50601002_13_dialog_content = "But...",
  ui_story_5060_50601002_14_dialog_content = "If we can't defeat Father...",
  ui_story_5060_50601002_15_dialog_content = "The numbers are too heavily skewed against us. This was a meaningless battle from the start.",
  ui_story_5060_50601002_16_dialog_content = "But even so, I have my own reasons for wanting to come back to this place.",
  ui_story_5060_50601002_17_dialog_content = "Me too.",
  ui_story_5060_50601002_18_dialog_content = "Maybe there's another way to solve this problem?",
  ui_story_5060_50601002_19_dialog_content = "Another way? Like what?",
  ui_story_5060_50601002_20_dialog_content = "<size=45>Yo, yo, yo!</size> What's the big idea, not inviting us to fight in such an epic battle?!",
  ui_story_5060_50601002_21_dialog_content = "That's pretty messed up, Tohru!",
  ui_story_5060_50601002_22_dialog_content = "It's the Rediesel Wrench!",
  ui_story_5060_50601002_23_dialog_content = "Stay back! This place is way too dangerous!",
  ui_story_5060_50601002_24_dialog_content = "You guys are heroes in the eyes of the Rediesel Wrench, you know!",
  ui_story_5060_50601002_25_dialog_content = "Thanks to you, the number of Eclipsites around here is at an all-time low!",
  ui_story_5060_50601002_26_dialog_content = "So it's only fair if we help you out too!",
  ui_story_5060_50601002_27_dialog_content = "Don't think you can run away with your tail between your legs, Fafnir. You still haven't beaten me, remember?",
  ui_story_5060_50601002_28_dialog_content = "Hmph. Who said I was running away?",
  ui_story_5060_50601002_29_dialog_content = "Deputy Captain Elma!",
  ui_story_5060_50601002_30_dialog_content = "Wow! You guys are here to help too?!",
  ui_story_5060_50601002_31_dialog_content = "Yes, we've also brought your favorite sweets.",
  ui_story_5060_50601002_32_dialog_content = "Wow, this is so incredible!",
  ui_story_5060_50601002_33_dialog_content = "After that last battle just now, I seriously needed to recover my magic!",
  ui_story_5060_50601002_34_dialog_content = "The Rediesel Wrench isn't too fond of working with you guys, but since Tohru and the others are in trouble, we're willing to set our differences aside for now.",
  ui_story_5060_50601002_35_dialog_content = "We must express our gratitude for this matter.",
  ui_story_5060_50601002_36_dialog_content = "Thankfully, we came across you during our desert patrol, and that's when we got the news about Elma and Miss Tohru's situation.",
  ui_story_5060_50601002_37_dialog_content = "Deputy Captain Elma and her crew have helped us a lot! We should repay their favor!",
  ui_story_5060_50601002_38_dialog_content = "Emperor of Demise, you told us earlier that you only trust your own judgment.",
  ui_story_5060_50601002_39_dialog_content = "Everyone you see here right now came to support Tohru and her friends.",
  ui_story_5060_50601002_40_dialog_content = "Tell me, do you still think our world is filthy?",
  ui_story_5060_50601002_41_dialog_content = "...",
  ui_story_5060_50601002_42_dialog_content = "You haven't been in this world for very long, Tohru.",
  ui_story_5060_50601002_43_dialog_content = "No matter what anyone says, you are completely different from these people, even down to your species.",
  ui_story_5060_50601002_44_dialog_content = "How did you earn their trust so quickly?",
  ui_story_5060_50601002_45_dialog_content = "Furthermore, how can you be sure that they won't hurt you?",
  ui_story_5060_50601002_46_dialog_content = "Answer me.",
  ui_story_5060_50601002_47_dialog_content = "We may be different species living in different worlds, but we're capable of understanding each other.",
  ui_story_5060_50601002_48_dialog_content = "This world isn't nearly as bad as you think, Father.",
  ui_story_5060_50601002_49_dialog_content = "Yes, war and prejudice still exist here, but at the same time...",
  ui_story_5060_50601002_50_dialog_content = "There's goodwill from people, such as Mr. Liu, the man who fed me his delicious dumplings.",
  ui_story_5060_50601002_51_dialog_content = "And the Illuminan soldiers, who are willing to fight by our side.",
  ui_story_5060_50601002_52_dialog_content = "And the Rediesel Wrench, who laughed with us as they showed us the beauty of the desert!",
  ui_story_5060_50601002_53_dialog_content = "And our friend, <size=45>PlayerName</size>, who unites us all.",
  ui_story_5060_50601002_54_dialog_content = "...",
  ui_story_5060_50601002_55_dialog_content = "Tohru is far more determined than you think.",
  ui_story_5060_50601002_56_dialog_content = "She shouldered the responsibility of working as Mr. Liu's delivery person, just so she could search for her missing friends.",
  ui_story_5060_50601002_57_dialog_content = "If she hadn't done that...",
  ui_story_5060_50601002_58_dialog_content = "This story never would have happened.",
  ui_story_5060_50601002_59_dialog_content = "The reason so many different species can get along here is because there's still a lot of goodwill in this world.",
  ui_story_5060_50601002_60_dialog_content = "Your name is PlayerName, correct?",
  ui_story_5060_50601002_61_dialog_content = "Yes.",
  ui_story_5060_50601002_62_dialog_content = "How rare. The determination burning in your eyes is just as fierce as Kobayashi's.",
  ui_story_5060_50601002_63_dialog_content = "Tohru must have truly earned the trust of you and your people.",
  ui_story_5060_50601002_64_dialog_content = "She serves as the link that connects all of you together.",
  ui_story_5060_50601002_65_dialog_content = "Is this what it looks like when different species interact as equals?",
  ui_story_5060_50601002_66_dialog_content = "Very well.",
  ui_story_5060_50601002_67_dialog_content = "For now, I will refrain from judging the filthiness of this world.",
  ui_story_5060_50601002_68_dialog_content = "At the very least, Tohru shouldn't become tainted so long as you're with her.",
  ui_story_5060_50601002_69_dialog_content = "Father.",
  ui_story_5060_50601002_70_dialog_content = "I will be waiting for you nearby. Furthermore, I will allow you to return to this world.",
  ui_story_5060_50601002_71_dialog_content = "Thank you, Father!",
  ui_story_5060_50601002_72_dialog_content = "He flew off.",
  ui_story_5060_50601002_73_dialog_content = "He sure likes beating around the bush... He could've just said that he cares about his daughter.",
  ui_story_5060_50601002_74_dialog_content = "This is great, Tohru! We finally managed to convince him!",
  ui_story_5060_50601002_75_dialog_content = "Ah... Elma...",
  ui_story_5060_50601002_76_dialog_content = "Don't fly over here just to hug me like this!",
  ui_story_5060_50601002_77_dialog_content = "<size=45>Get! Off! Me!</size>",
  ui_story_5060_50601002_78_dialog_content = "What's gonna happen to those bad guys?",
  ui_story_5060_50601002_79_dialog_content = "You mean the smugglers?",
  ui_story_5060_50601002_80_dialog_content = "I'm sure the Rediesel Wrench and the Guild will capture them in no time.",
  ui_story_5060_50601002_81_dialog_content = "As for the dragon egg, I'm sure its mother will find it soon enough.",
  ui_story_5060_50601002_82_dialog_content = "I just hope it doesn't hold a grudge against all Aurorians because of this.",
  ui_story_5060_50601002_83_dialog_content = "Dragons don't reproduce easily.",
  ui_story_5060_50601002_84_dialog_content = "If they are willing to reproduce here, it proves that there are still creatures in this world that they are willing to trust.",
  ui_story_5060_50601002_85_dialog_content = "Are you talking about the goodwill between different species?",
  ui_story_5060_50601002_86_dialog_content = "If so, I'm sure that dragon will sense it too.",
  ui_story_5060_50601002_87_dialog_content = "And once this little one is born, it'll start a brand new story of its own!",
  ui_story_5060_50601002_88_dialog_content = "I just hope that goodwill exists in its story too.",
  ui_story_5060_50601002_89_dialog_content = "Just like it existed in our adventures in this world.",
  ui_story_5060_50601002_90_dialog_content = "We can never decide the course of its story. That's for this little one to choose.",
  ui_story_5060_50601002_91_dialog_content = "Alright, I think it's time to go back to Mr. Liu's restaurant and retire from being a delivery girl.",
  ui_story_5060_50601101_1_dialog_content = "Everyone worked so hard to help us, so let me treat you all to a nice meal once I get paid!",
  ui_story_5060_50601101_2_dialog_content = "That sounds great! After all, it's rare to see Tohru in such a generous mood!",
  ui_story_5060_50601101_3_dialog_content = "We can't use this world's money back home!",
  ui_story_5060_50601101_4_dialog_content = "Is this really Mr. Liu's restaurant?",
  ui_story_5060_50601101_5_dialog_content = "That's right, now come on in!",
  ui_story_5060_50601101_6_dialog_content = "But... all the signs have been torn down!",
  ui_story_5060_50601101_7_dialog_content = "Huh? Is that how people in your world show that their shop is closed for the day? By taking down all of your signs?",
  ui_story_5060_50601101_8_dialog_content = "Of course not! No matter how you look at it, this place seems like it's closed for good!",
  ui_story_5060_50601101_9_dialog_content = "Good to see you back, Miss Tohru.",
  ui_story_5060_50601101_10_dialog_content = "Looks like you've found all your companions. Now, have you found the way to get back home?",
  ui_story_5060_50601101_11_dialog_content = "Yes, and it's thanks to you and everyone else.",
  ui_story_5060_50601101_12_dialog_content = "That's fantastic.",
  ui_story_5060_50601101_13_dialog_content = "Pardon me, Mr. Liu, but what's going on here? Who vandalized the shop by tearing down your signs?!",
  ui_story_5060_50601101_14_dialog_content = "Miss Tohru, please don't get angry.",
  ui_story_5060_50601101_15_dialog_content = "The thing is...",
  ui_story_5060_50601101_16_dialog_content = "From this day on, Liu's Restaurant is closing its doors.",
  ui_story_5060_50601101_17_dialog_content = "<size=45>What?!</size>",
  ui_story_5060_50601101_18_dialog_content = "Was it because I didn't deliver our orders fast enough?",
  ui_story_5060_50601101_19_dialog_content = "It has nothing to do with you, Miss Tohru.",
  ui_story_5060_50601101_20_dialog_content = "It's just that... the restaurant's business hasn't been great.",
  ui_story_5060_50601101_21_dialog_content = "Our menu hasn't kept up with the latest culinary trends, and the decor doesn't match our discerning customers' expectations.",
  ui_story_5060_50601101_22_dialog_content = "As you know, the demi-human Aurorians we hire often face harassment from Lumo nobles.",
  ui_story_5060_50601101_23_dialog_content = "The much-anticipated delivery service didn't go as smoothly as we hoped.",
  ui_story_5060_50601101_24_dialog_content = "To be honest, I had considered closing down even before meeting you, Miss Tohru.",
  ui_story_5060_50601101_25_dialog_content = "Fortunately, thanks to you, my failing business had the chance to witness the incredible world of maid culture before closing.",
  ui_story_5060_50601101_26_dialog_content = "I don't think any of this is your fault, Mr. Liu.",
  ui_story_5060_50601101_27_dialog_content = "The food you make is absolutely delicious! There's no way you could be in the wrong here!",
  ui_story_5060_50601101_28_dialog_content = "This is all because of those bigoted nobles and their private soldiers! Someone needs to stop them!",
  ui_story_5060_50601101_29_option_content = "I can help you!",
  ui_story_5060_50601101_30_option_content = "Don't worry, I know some people.",
  ui_story_5060_50601101_31_dialog_content = "Thanks for being so comforting.",
  ui_story_5060_50601101_32_dialog_content = "But that's how the world works. My abilities alone are no longer enough to keep the restaurant going, and this is just unavoidable.",
  ui_story_5060_50601101_33_dialog_content = "(It feels like Mr. Liu has already lost all faith in the nobles and military officers of Lumopolis...)",
  ui_story_5060_50601101_34_dialog_content = "(But still, someone needs to do something about these rotten attitudes.)",
  ui_story_5060_50601101_35_dialog_content = "(I think I'll go have a talk with her.)",
  ui_story_5060_50601101_36_dialog_content = "Miss Tohru, could you try to talk to the owner and persuade him?",
  ui_story_5060_50601101_37_dialog_content = "Mr. Liu, while I did see a couple of Lumo nobles with prejudiced views towards demi-human Aurorians...",
  ui_story_5060_50601101_38_dialog_content = "I also saw plenty of pure-blooded Aurorians, Lumopolis soldiers, and ordinary merchants in your restaurant.",
  ui_story_5060_50601101_39_dialog_content = "All of them gathered together here because of you!",
  ui_story_5060_50601101_40_dialog_content = "That's right!",
  ui_story_5060_50601101_41_dialog_content = "Food has the power to solve any conflict!",
  ui_story_5060_50601101_42_dialog_content = "That only works for you, Elma.",
  ui_story_5060_50601101_43_dialog_content = "But the food here really is tasty.",
  ui_story_5060_50601101_44_dialog_content = "For the demi-humans who work here, for the countless, unfamiliar guests that eat here... and for myself as well, your restaurant serves as a link that connects everyone. No private soldier or noble could ever take away the feelings and connections that are made here!",
  ui_story_5060_50601101_45_dialog_content = "I just finished telling an elder of mine about the power of different people coming together to fight for a common goal. Whether it's dragons or Aurorians, no obstacle is too great to overcome when we combine our strengths!",
  ui_story_5060_50601101_46_dialog_content = "I think now is the time to make good on that promise—To show that these words are more than just words!",
  ui_story_5060_50601101_47_dialog_content = "Well said, Miss Tohru. If you think it's worth it, I'll give it another shot.",
  ui_story_5060_50601101_48_dialog_content = "I just hope those nobles in Lumopolis can stop harassing us.",
  ui_story_5060_50601101_49_dialog_content = "Don't worry, if we run into anyone who won't listen to reason, I'll send them straight to hell, free of charge!",
  ui_story_5060_50601101_50_dialog_content = "Just don't get too carried away.",
  ui_story_5060_50601101_51_dialog_content = "Fine, fine!",
  ui_story_5060_50601101_52_dialog_content = "I agree with Tohru's statement just now.",
  ui_story_5060_50601101_53_dialog_content = "If you want to change the fate of the world, you may as well start with changing the fate of a single restaurant.",
  ui_story_5060_50601101_54_dialog_content = "And we can start by fixing up and cleaning the dining area!",
  ui_story_5060_50601101_55_dialog_content = "I can help develop new dishes, if that's okay?",
  ui_story_5060_50601101_56_dialog_content = "No way. You'll just eat them all.",
  ui_story_5060_50601101_57_dialog_content = "Don't worry, Mr. Liu.",
  ui_story_5060_50601101_58_dialog_content = "I just spoke to a good friend of mine. She says that as the daughter of the City Lord, she'll do everything she can to make things right.",
  ui_story_5060_50601101_59_dialog_content = "From now on, you won't have to worry about anyone harassing you or your restaurant ever again. I'm sure of it.",
  ui_story_5060_50601101_60_dialog_content = "I-Is this for real?! Oh my, I'm not dreaming, am I?!",
  ui_story_5060_50601101_61_dialog_content = "Thank you all! I can't express my gratitude enough!",
  ui_story_5060_50601101_62_dialog_content = "Come on, today's on me. Everyone, dig in and feast to your heart's content!",
  ui_story_5060_50601101_63_dialog_content = "Esteemed guests, here's the new special you ordered: Golden Seafood Soup. Be careful, it's hot.",
  ui_story_5060_50601101_64_dialog_content = "Certainly, it'll be ready in no time. Just a second, now.",
  ui_story_5060_50601101_65_dialog_content = "Table five, one serving of Snowy Tofu!",
  ui_story_5060_50601101_66_dialog_content = "This place is really busy! It's obvious that everyone here likes the food.",
  ui_story_5060_50601101_67_dialog_content = "Looks like Mr. Liu was just making excuses earlier. The real problem was all the harassment coming from those nobles and private soldiers after all.",
  ui_story_5060_50601101_68_dialog_content = "Good thing those guys won't be a problem anymore.",
  ui_story_5060_50601101_69_dialog_content = "Things couldn't be any better!",
  ui_story_5060_50601101_70_dialog_content = "Are you sure you're not in a hurry to go back, Tohru? I'm pretty sure your father is still waiting for you.",
  ui_story_5060_50601101_71_dialog_content = "It's fine, I still want to see more of this world.",
  ui_story_5060_50601101_72_dialog_content = "There's so much beauty in your world, and it's not as dangerous as I first thought.",
  ui_story_5060_50601101_73_dialog_content = "But maybe that's just because I had you, Elma, and the others with me the whole time, PlayerName.",
  ui_story_5060_50601101_74_dialog_content = "Are you sure you'll be able to come back?",
  ui_story_5060_50601101_75_dialog_content = "Doubting your friend's words so soon, PlayerName?",
  ui_story_5060_50601101_76_dialog_content = "Hahaha, just kidding! Don't worry, I'm sure we'll be back soon enough.",
  ui_story_5060_50601101_77_dialog_content = "We'll come find you as soon as we return!",
  ui_story_5060_50601101_78_dialog_content = "I'm looking forward to it, but don't take too long, okay? After all...",
  ui_story_5060_50601101_79_dialog_content = "We're friends for life now.",
  ui_story_5060_50601101_80_dialog_content = "PlayerName!",
  ui_story_5060_50601101_81_dialog_content = "Aaaah—Get out of the way!!",
  ui_story_5060_50601101_82_dialog_content = "What's the matter, Vice? Why are you in such a panic?",
  ui_story_5060_50601101_83_dialog_content = "Looks like your training courses back in Illumina have ended early.",
  ui_story_5060_50601101_84_dialog_content = "Th-That's because someone told me you were in danger! I rushed over here as soon as I heard!!",
  ui_story_5060_50601101_85_dialog_content = "You're not hurt, are you?!",
  ui_story_5060_50601101_86_option_content = "Relax, I'm perfectly fine.",
  ui_story_5060_50601101_87_dialog_content = "I'm so relieved.",
  ui_story_5060_50601101_88_option_content = "I'm pretty hurt.",
  ui_story_5060_50601101_89_dialog_content = "You ran into me so hard that now my head hurts.",
  ui_story_5060_50601101_90_dialog_content = "Want me to give it a little pat?",
  ui_story_5060_50601101_91_dialog_content = "Pain, pain, go away!",
  ui_story_5060_50601101_92_dialog_content = "Okay, I feel better now.",
  ui_story_5060_50601101_93_dialog_content = "Hey PlayerName, what's that in your hand?",
  ui_story_5060_50601101_94_dialog_content = "Oh, just a gift from a friend.",
  ui_story_5060_50601101_95_dialog_content = "I made some new friends while you were away. They already left, but I'm sure we'll see them again very soon.",
  ui_story_5060_50601101_96_dialog_content = "They were a bunch of nice people. Super amazing, really."
}
return config
